(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-modm-efficient-serving-for-image-gen-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-1\">一 · 一个晚高峰的在线出图服务现场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-2\">二 · 旧方案：单模型固定步数与“不路由的模型池”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-3\">三 · 为什么非改不可：CFG 合并与 VAE 解码的摊薄逻辑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-4\">四 · 一个具体请求的代价账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-5\">五 · 旧方案的显存天花板与调度复杂度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-6\">六 · 工程判断：从“固定配置”到“请求级决策”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-7\">七 · 请求难度分布决定档位收益的上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-8\">八 · 并发与批大小：档位内合并的可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-9\">九 · SLO 与长尾：lambda 是尾延迟的旋钮，不是装饰</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-10\">十 · 负载塑造方案：路由阈值与档位映射的校准闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-11\">十一 · 方案限制负载：显存驻留与评估器开销构成的硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-12\">十二 · 测量口径清单：把可核查的量固定下来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-13\">十三 · 路由式服务的负载边界：难度分布、队列反馈与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-14\">十四 · 档位异构下的 kernel 选择：为什么不能一套 kernel 打天下</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-15\">十五 · 数据类型：FP16/BF16 是基线，FP8 与 NVFP4 是档位差异化手段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-16\">十六 · 累加精度与误差传播：MMA 内部是 FP32，跨步是另一回事</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 如何改变档位设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-18\">十八 · 公式逐项落地：从路由目标到 kernel 配置的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-19\">十九 · 工程判断：精度与 kernel 配置应随档位冻结，而非全局统一</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-20\">二十 · 显存账本的三个账户：权重、激活、KV 式中间缓存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-21\">二十一 · 分页与复用：把中间缓存做成可回收的页</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-22\">二十二 · 压缩与卸载：权重比特数与档位驻留的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-23\">二十三 · 带宽瓶颈的位置：CFG 合并与 VAE 解码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-24\">二十四 · 可复算的显存预算：一个具体算例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-25\">二十五 · 账本与调度的接口：释放时机决定尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-26\">二十六 · 连续批处理在扩散采样循环里的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-27\">二十七 · Chunked prefill 的扩散对应物：分步预填与潜变量分段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-28\">二十八 · 优先级、抢占与档位队列的联合决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-29\">二十九 · 分离式预填/解码在扩散服务里的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-30\">三十 · 尾延迟的压制：从队列权重到步边界调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-31\">三十一 · 档位即并行域：MoDM 的切分边界在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-32\">三十二 · NVLink 5 与 NVSwitch：All-Reduce 什么时候真的便宜</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-33\">三十三 · 通信成为瓶颈的三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-34\">三十四 · NIXL 传输：档位间与节点间的数据面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-35\">三十五 · 把通信代价写进路由目标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-36\">三十六 · 路由式服务在并行拓扑上的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-37\">三十七 · 精度塌陷：误路由是静默的，不是崩溃的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-38\">三十八 · OOM：显存驻留是常数项，不是峰值项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-39\">三十九 · 批抖动：队列长度进了目标函数，抖动就会传导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-40\">四十 · 尾延迟：均值好看不代表 SLO 达标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-41\">四十一 · 静默降级与监控面：把不可见变成可告警</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-42\">四十二 · 路由式服务的失效边界与可观测性设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-43\">四十三 · 口径的第一原则：先分清“论文报了什么”与“论文没报什么”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-44\">四十四 · 模型档位与硬件档位：两个维度不能混为一谈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-45\">四十五 · batch、CFG 合并与并发：等效批大小的口径陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-46\">四十六 · 指标口径：TTFT/TPOT 在扩散服务里要重新定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-47\">四十七 · 功耗与带宽：论文未报，但必须纳入口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-48\">四十八 · 哪些提升不可比：四条硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-49\">四十九 · 口径边界：哪些提升能横向比较，哪些不能</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-50\">五十 · 迁移的第一道闸：难度信号从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-51\">五十一 · 路由目标函数要重写代价项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-52\">五十二 · 模型池的显存驻留是硬上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-53\">五十三 · 批合并与 CFG 合并的适用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-54\">五十四 · 规模上限与不适用场景</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-modm-efficient-serving-for-image-gen-2025-sec-55\">五十五 · 迁移边界：哪些模型能进池，哪些负载不该路由</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:548px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 547.8 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"465.8\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入接入层，提取提示词与采样参数，交由轻量难度评估器打分。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"465.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">路由器结合难度分数与各档位队列长度，选择目标扩散模型档位。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"465.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">同档位请求按批合并，CFG 的正负分支合并为一次前向以摊薄算力。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"465.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按档位配置的步数与采样器执行扩散/流匹配迭代，中间潜变量驻留显存。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"465.8\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样完成后统一批合并做 VAE 解码，输出图像并回传，释放显存与缓存。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-1\">一 · 一个晚高峰的在线出图服务现场</h3>\n<p>设想一个面向 C 端应用的文生图服务：接入层每秒收到数十条提示词，其中大量是“一只猫坐在窗台上”“城市夜景霓虹”这类结构简单、语义收敛的请求，也夹杂着“三位宇航员在失重舱内传递一只发光的玻璃球，背景是地球弧线，逆光”这类构图复杂、细节约束密集的请求。服务跑在单卡或单节点 GPU 上，SLO 以端到端时延与质量下限双重约束。工程团队面对的第一个事实是：扩散与流匹配采样器在部署时被固化成“固定步数 + 固定模型规模”，整条推理栈只认识一个骨干网络。于是同一套算力被均匀地摊到每一条请求上——简单请求被过度计算，困难请求又质量不足。这不是调参能解决的问题，而是服务形态与请求分布之间的结构性错配。</p>\n<p>在这个现场里，痛点可以被拆成三条可测量的代价。其一是算力代价：固定步数意味着每条请求都走完整条采样轨迹，平均采样步数不随负载难度分布变化，简单请求的算力被白白烧掉。其二是显存与带宽代价：CFG 批合并把正负分支拼成一个批，等效批大小翻倍但前向次数减半；VAE 解码阶段又要为每条请求单独驻留潜变量与解码中间张量，显存占用随并发线性上升。其三是尾延迟代价：单一模型无法通过“少算一点”来吸收突发流量，队列一旦堆积，所有请求一起变慢，SLO 直接失守。这三条代价共同指向一个判断：固定模型、固定步数的服务栈，必须改成按请求难度分配算力的路由式服务。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-2\">二 · 旧方案：单模型固定步数与“不路由的模型池”</h3>\n<p>论文之前的主流做法有两种，都不足以支撑混合难度负载。第一种是单一扩散模型固定步数服务：整个服务只部署一个骨干，采样步数与 CFG 策略全局写死。它的优点是实现简单、批调度单一、显存驻留可预测；缺点是算力分配与请求难度完全脱钩。对简单请求，它做了大量冗余的去噪迭代；对困难请求，它又没有额外的算力可加。质量与吞吐被同一个固定点锁死，服务方只能在“整体多算”与“整体少算”之间二选一。</p>\n<p>第二种是固定档位不路由的模型池服务：部署多个不同规模的骨干，但请求到档位的映射是静态的，比如按提示词长度或租户等级硬分。它缓解了“一个模型服务所有请求”的规模错配，却没有解决难度错配——静态映射不认识请求的真实难度，也无法感知各档位当前的队列长度。高峰时热点档位排队，冷档位空转，尾延迟照样恶化。更关键的是，多档位模型池要求各档位权重常驻显存，档位数量增加会线性抬升显存驻留成本，在单卡容量约束下，静态模型池很快撞到显存天花板。</p>\n<p>两条旧路线的共同缺陷可以写成一个服务侧的代价结构：设请求难度为 s(x)，档位 k 的单位算力代价为 c_k，则旧方案把 s(x) 与 c_k 解耦，等价于对所有请求取同一个 k 与同一组步数。平均计算量因此不随负载难度分布自适应下降，显存驻留也不随队列长度动态收缩。这正是 MoDM 要改的地方：把“选哪个模型、走多少步”从部署期的静态决定，变成请求级的联合决策。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-3\">三 · 为什么非改不可：CFG 合并与 VAE 解码的摊薄逻辑</h3>\n<p>要理解旧方案为何在服务化场景下不可持续，必须看清两个固定开销的来源。第一个是 CFG 正负分支：无分类器引导要求每个去噪步做两次前向，一次条件分支、一次无条件分支。旧栈若逐请求执行，前向次数翻倍，注意力与 DiT 算力开销直接翻倍。把正负分支在档位内合并为一个批、一次前向完成，等效批大小翻倍而前向次数减半——这是纯服务侧的批组织收益，与模型本身无关，但只有在“同档位内多请求可合并”的前提下才拿得到。固定单模型服务若并发不足，批合并不起来，这笔收益就落空。</p>\n<p>第二个是 VAE 解码：采样结束后潜变量要过解码器还原成像素，解码阶段的显存与带宽占用按请求计。逐请求解码意味着单位请求的解码开销无法摊薄，并发一高，解码段就成为显存与带宽的瓶颈。共享 VAE 解码批把多个请求的潜变量拼批解码，降低解码阶段单位请求的显存与带宽占用。但拼批解码要求这些请求在同一时刻完成采样——旧栈里各请求步数相同、节奏一致，看似容易拼批，实则因为无法按难度分流而把所有请求压在同一个长队列里，解码批的等待时间被拉长，端到端时延反而变差。</p>\n<div class=\"formula\">$$\\hat{k}=\\arg\\min_{k\\in\\{1,\\dots,K\\}}\\ \\Big(\\frac{s(x)}{c_k}+\\lambda\\,q_k\\Big),\\quad \\text{s.t.}\\ \\sum_{k} b_k \\le B_{\\max}$$</div>\n<p>上式是 MoDM 给出的路由目标，也是旧方案缺失的那一层决策。s(x)/c_k 把难度分数折算成单位算力代价下的“性价比”，λ·q_k 把档位队列长度作为负载惩罚项；约束项则提醒：多档位权重常驻显存，档位集合的显存预算 b_k 之和不能超过单卡容量 B_max。旧方案相当于把这个优化问题退化成“k 固定、q_k 不可见”，于是既拿不到难度自适应的算力节省，也拿不到队列感知的负载均衡。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-4\">四 · 一个具体请求的代价账</h3>\n<p>取一条中等偏简单的请求：提示词短、主体单一、无复杂空间关系。在旧栈里，它走完整采样轨迹，CFG 双分支逐请求执行，采样结束后单独解码。它的端到端时延由三段时间构成：采样段（固定步数 × 双分支前向）、解码段（单请求 VAE）、排队段（与所有其他请求共享同一队列）。由于步数与模型规模固定，这条请求的采样段无法压缩；由于不与其他请求拼批，CFG 与 VAE 的摊薄收益都拿不到；由于队列里混着困难请求，它的排队段被难样本拖长。三项叠加，简单请求付出了远超其质量所需的算力与等待。</p>\n<p>同一时刻到达一条困难请求：多主体、强空间约束、逆光细节。旧栈给它的算力与简单请求完全相同——步数一样、模型一样。结果是质量不足：固定步数不足以收敛复杂构图，固定规模不足以表达细节约束。服务方若想提升这条请求的质量，只能全局加步数或全局换大模型，代价是简单请求被进一步过度计算，平均算力整体上抬。这就是“简单请求被过度计算、困难请求又质量不足”在同一套固定配置下的必然共存。</p>\n<p>把两条请求放在一起看，旧栈的代价结构清晰了：平均采样步数不随负载难度分布下降，CFG 与 VAE 的摊薄收益受制于统一节奏，显存驻留不随队列长度收缩，尾延迟无法通过分流吸收。MoDM 的切入点正是把这三笔账拆开：难度评估器给每条请求打分，路由器按 s(x)/c_k + λ·q_k 选档位，简单请求走小模型少步数，困难请求走大模型多步数，同档位内做批合并与 CFG 合并，解码阶段统一拼批。平均计算量随负载分布自适应下降，显存与带宽开销随档位与批组织被摊薄。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-5\">五 · 旧方案的显存天花板与调度复杂度</h3>\n<p>旧方案还有一个不显眼但致命的约束：显存。单卡容量决定了能驻留几个档位的权重、能开多大的批、能缓存多少中间潜变量。固定单模型服务的显存账最好算——一份权重、一个批、一份解码缓冲；但它的算力账最差。固定档位模型池把显存账变差：每个档位一份权重常驻，档位数量增加线性抬升驻留成本，KV 式中间缓存还要按档位独立维护。在单卡上，档位一多就撞墙；档位一少，路由的收益又有限。论文的消融也指向这一点：档位过少收益有限，过多则显存与调度开销上升。</p>\n<p>调度复杂度是另一笔隐性代价。档位切换意味着请求要在不同队列、不同批组织、不同步数配置之间迁移；批合并要求同档位请求节奏对齐；CFG 合并要求正负分支同批；VAE 拼批要求采样完成时刻接近。旧栈把这些复杂度全部压平成“一个队列、一种节奏”，实现简单但失去了所有自适应空间。MoDM 把这层复杂度显式化：路由器依据评估分数与当前各档位队列长度做联合决策，队列过长时通过 λ 权重把请求导向低负载档位，避免热点档位排队导致尾延迟恶化。代价是调度器本身要维护多档位状态，收益是尾延迟与平均算力同时可控。</p>\n<p>还有一笔固定成本不能忽略：难度评估器为每次请求引入额外前向。它用轻量特征给出难度分数 s(x)，开销小于一次完整去噪步，但它是每条请求都要付的固定成本，且评估误差会直接转化为误路由风险——难样本被误判为简单、路由到小模型，质量回退且难以在线发现。这笔成本必须与节省的采样步数权衡：当负载以简单请求为主时，评估器开销占比上升；当负载难度分布宽时，路由节省的算力足以覆盖评估开销。论文未给出具体吞吐、质量指标与硬件配置数字，这条权衡线需要以原文实验为准，不能直接引用未给出的数字做容量承诺。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-6\">六 · 工程判断：从“固定配置”到“请求级决策”</h3>\n<p>把旧方案的痛点收敛成一句工程判断：扩散服务的成本结构不是由模型单点决定的，而是由“模型档位 × 步数 × 批组织 × 解码批”这四个维度的联合配置决定的。旧栈把这四个维度在部署期全部冻结，于是服务只能在一个固定点上运行，无法随请求难度分布与队列状态移动。MoDM 的贡献不在于发明了新的扩散骨干，而在于把这四个维度变成请求级的决策变量：难度评估器提供 s(x)，路由器用 s(x)/c_k + λ·q_k 在档位间分配算力，档位内用批合并与 CFG 合并摊薄前向，解码段用共享批摊薄 VAE。这套结构对 Blackwell 档位上的显存分区、批调度与量化策略是可组合的——各档位权重可用 NVFP4/FP8 压缩以缓解驻留压力，档位内批并行与档位间独立部署互不干扰。</p>\n<p>对做容量规划的工程师而言，这一部分留下的可操作结论是：先量化自己负载的难度分布，再看固定配置下简单请求的算力冗余与困难请求的质量缺口各占多少；若两者同时显著，单模型固定步数的栈就已经到了非改不可的节点。此时要评估的不是“换更大的模型”，而是“能不能把算力按请求分配”——而这正是路由式服务要回答的问题，也是后续部分要展开的模型池、批调度与解码组织的设计空间。</p>\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-7\">七 · 请求难度分布决定档位收益的上界</h3>\n<p>MoDM 的路由收益不是均匀地摊在每条请求上的，它严格依赖负载中难度分数的分布形状。设难度评估器输出 s(x)，档位集合为 {1,…,K}，单位算力代价 c_k 随 k 单调上升，则路由目标 <span class=\"formula\">$$\\hat{k}=\\arg\\min_{k}\\Big(\\frac{s(x)}{c_k}+\\lambda q_k\\Big)$$</span> 的实质是：把 s(x) 与 c_k 的比值压到最小。若负载中绝大多数请求的 s(x) 落在最低档位区间，平均采样步数与平均参数量都会显著下降；反之，若分布是双峰甚至长尾右偏——大量简单提示词加一小撮极端复杂提示词——那么路由的收益主要体现在“不把大模型浪费在简单请求上”，而不是“把小模型用在困难请求上”。工程上要区分这两种形态：前者是均值下降，后者是尾部保护。测量口径必须能同时刻画两者，否则只看平均计算量会掩盖尾部的质量回退。</p>\n<p>可核查的测量方式：对固定提示词集合离线跑一遍评估器，记录 s(x) 的经验分布（分位数 p50/p90/p99、直方图），并记录每个分位区间在固定档位映射下被路由到的档位。这条“分数—档位”映射表是后续所有容量讨论的基线。注意评估器本身是额外前向，它的开销按请求计，属于固定成本项，不随档位变化——所以难度分布越集中在低档位，评估器开销在端到端时延中的占比越高，这是路由方案在小模型档位上必须正视的摊销问题。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-8\">八 · 并发与批大小：档位内合并的可行域</h3>\n<p>档位内批合并与 CFG 合并是 MoDM 摊薄算力的两个杠杆。CFG 正负分支拼成一个批一次前向，等效批大小翻倍而前向次数减半，直接减少注意力与 DiT 的调用次数；但等效批大小翻倍也意味着单次前向的激活显存与带宽占用上升。设档位 k 的批大小为 b_k，CFG 合并后实际前向批为 2b_k，则单卡显存约束近似为 <span class=\"formula\">$$W_k + 2b_k\\cdot A_k + M_k \\le B_{\\max}$$</span> 其中 W_k 为该档位权重常驻、A_k 为单样本激活、M_k 为 KV 式中间缓存。这条不等式直接给出每个档位的批大小上界，而批大小上界又反过来限制该档位能吸收的并发。多档位模型池要求各档位权重常驻，档位数量增加会线性抬升 W_k 总和，因此“档位多”与“批大”在单卡容量下是竞争关系——这正是消融中档位过多导致显存与调度开销上升的机制来源。</p>\n<p>测量口径：按档位分别记录实际批大小的时间序列、批内请求数、CFG 合并前后前向次数、以及因显存不足触发的批切分次数。批切分会把一次大前向拆成多次小前向，等效于放弃部分合并收益，是吞吐下降的直接信号。另一个必须记录的量是批内请求的难度方差——同一档位内若混入接近档位边界的请求，其步数配置与批内其他请求不一致，会导致批内串行等待或步数对齐浪费。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-9\">九 · SLO 与长尾：lambda 是尾延迟的旋钮，不是装饰</h3>\n<p>路由目标里的 λq_k 项是队列长度惩罚，它的作用是在热点档位排队时把请求导向低负载档位。这带来一个直接的工程判断：λ 越大，负载均衡越激进，但误路由概率上升——请求被推到算力不匹配的档位，质量或步数配置偏离最优。λ 越小，路由越忠于难度分数，但热点档位队列堆积会直接恶化尾延迟。SLO 若以端到端时延 p99 为约束，λ 的校准必须以尾延迟为目标函数，而不是以平均时延为目标函数。论文未给出大规模并发下的尾延迟数据，这意味着 λ 的取值在部署时只能靠在线观测的队列长度与超时率来迭代，不能直接引用任何吞吐数字做容量承诺。</p>\n<p>长尾的另一个来源是 VAE 解码。解码阶段统一做批合并以摊薄开销，但批合并意味着一个请求的解码要等批内其他请求采样完成——批内最慢请求决定了解码开始时刻。若批内混有高步数请求，低步数请求的解码被推迟，尾延迟被批内最大步数拉长。测量口径应记录“采样完成到解码开始”的等待时间分布，以及解码批的批内步数极差。这个量在固定步数服务里不存在，是路由式服务特有的尾延迟来源。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-10\">十 · 负载塑造方案：路由阈值与档位映射的校准闭环</h3>\n<p>方案不是被动接受负载，它反过来重塑负载的观测形态。路由阈值与档位映射的校准依据离线采样的难度分布与各档位质量—步数曲线，确定分数到档位的分界点；上线后按队列长度动态调整路由权重。这个闭环的关键在于：一旦阈值偏移，被观测到的“各档位队列长度”就变了，而队列长度又是路由决策的输入，于是形成反馈。若阈值把过多请求压向小档位，小档位队列变长、q_k 上升，λ 项把后续请求推向大档位，造成档位间振荡。工程上要监控路由命中率的稳定性（单位时间内档位切换次数的分布），振荡会表现为档位命中率的高频抖动，同时伴随批大小频繁变化与批切分次数上升。</p>\n<p>可核查的校准口径：固定一批代表性提示词，扫描阈值分界点，记录每个分界点下的档位命中分布、平均步数、以及离线质量指标（论文未给出具体指标数值，需以原文为准）。这条曲线的作用是找出“收益饱和点”——档位再细分带来的平均计算量下降已经小于显存驻留与调度复杂度的上升。消融中档位过少收益有限、过多则开销上升，正是这条曲线的两端。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-11\">十一 · 方案限制负载：显存驻留与评估器开销构成的硬边界</h3>\n<p>多档位模型池的显存驻留是硬约束：各档位权重常驻，档位数量线性抬升驻留成本，单卡容量决定了 K 的上界。这不是可以靠调度绕开的——权重不在显存里就得换入换出，换入换出的带宽代价在采样迭代的粒度上无法隐藏。因此方案对负载的限制体现在：并发上限由最热档位的批大小上界决定，而不是由总算力决定；当负载难度分布整体右移（更多困难请求），热档位从小档位切换到大档位，大档位的 W_k 更大、批大小上界更小，可吸收并发反而下降。这是一个反直觉的容量特性：负载变难时，系统吞吐上限下降的速度快于平均计算量上升的速度。</p>\n<p>评估器开销是另一条边界。它按请求计、与档位无关，因此在低难度负载下，评估器前向在端到端时延中的占比被放大。若评估器本身是一个小模型前向，其延迟与最小档位的一次采样步同量级，则在“简单请求走小模型少步数”的路径上，评估器可能吃掉节省下来的步数收益。测量口径必须把评估器延迟单独列出，并与最小档位单步延迟做比值；这个比值决定了路由方案在低难度负载下是否还有净收益。论文未给出该比值，部署时应把它作为上线前的必测项。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-12\">十二 · 测量口径清单：把可核查的量固定下来</h3>\n<p>综合上述，本部分主张的测量口径应包含以下可核查项，且每项都对应一个具体机制或代价：难度分数经验分布（分位数与直方图）对应路由收益上界；分数—档位映射表对应阈值校准；按档位的批大小时间序列与批切分次数对应 CFG 合并与显存约束；批内步数极差与“采样完成到解码开始”等待时间对应 VAE 共享批的尾延迟；档位命中率抖动对应 λ 反馈振荡；评估器延迟与最小档位单步延迟之比对应固定成本摊销；各档位权重驻留总和与 B_max 之比对应档位数量上界。</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>对应机制</th><th>影响的系统代价</th></tr></thead><tbody><tr><td>s(x) 分位数与直方图</td><td>难度评估与路由收益</td><td>平均采样步数、平均参数量</td></tr><tr><td>档位命中率抖动</td><td>λq_k 反馈</td><td>尾延迟、批大小稳定性</td></tr><tr><td>批切分次数</td><td>CFG 合并与显存约束</td><td>吞吐、前向调用次数</td></tr><tr><td>解码等待时间</td><td>VAE 共享批</td><td>p99 端到端时延</td></tr><tr><td>评估器/单步延迟比</td><td>固定成本摊销</td><td>低难度负载净收益</td></tr></tbody></table>\n<p>这些量共同构成一个判断：MoDM 的负载形态不是外部给定常量，而是被路由阈值、档位数量与 λ 共同塑造的变量。工程上先固定测量口径，再谈档位数量与阈值，否则任何“平均计算量下降”的表述都无法定位到具体机制上。论文报告混合负载下平均计算量下降且质量维持，但吞吐比例、质量指标与硬件配置未给出，因此上述口径的实测值必须来自部署侧自己的采集，不能引用未给出的数字做 SLO 承诺。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-13\">十三 · 路由式服务的负载边界：难度分布、队列反馈与尾延迟</h3>\n<p>MoDM 的收益完全取决于请求难度分布的形状，而非平均难度。设难度分数密度为 f(s)，档位分界点为 τ_k，则路由到档位 k 的请求比例为 ∫f(s)ds（区间 [τ_{k-1}, τ_k]），平均采样步数为 Σ_k π_k·n_k，其中 π_k 为该比例、n_k 为档位步数。当负载集中在分界点附近时，评估器的小误差会成批改变路由结果，档位命中率剧烈抖动；当负载呈双峰（大量极简提示词与少量高难提示词）时，中间档位几乎空转却仍常驻显存，性价比最差。可核查口径是：按固定时间窗统计各档位命中率、难度分数直方图与分界点邻域请求占比，三者共同决定路由是否稳定。</p>\n<p>队列反馈项 λ·q_k 是这套方案唯一对抗尾延迟的手段，但它同时是失效源。λ 过大时路由器把难请求压向低负载的小档位，质量回退且不可在线察觉；λ 过小时热点档位堆积，端到端时延由排队而非采样主导。工程上应把 λ 与档位队列阈值一起标定，并监控“误路由率”——即小档位输出被判为质量不达标的比例，该指标只能靠离线抽检或轻量质量代理获得，属于服务侧固定成本。批大小由队列阈值与超时共同决定，超时过短则批合并失效、CFG 合并摊薄不了 VAE 与注意力开销；过长则小档位请求被迫等待，抵消少步数带来的延迟优势。</p>\n<p>显存是硬边界：K 个档位权重常驻使驻留成本随 K 线性上升，单卡容量下 K 的实际上限往往由最大档位加中间缓存决定，而非总算力。档位切换与批合并带来的调度复杂度在高峰时表现为队列堆积，论文未给出大规模并发下的尾延迟数据，因此 SLO 承诺不能引用未给出的吞吐数字，只能以“档位命中率稳定、误路由率受控、队列长度有界”作为可验证的替代口径。</p>\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-14\">十四 · 档位异构下的 kernel 选择：为什么不能一套 kernel 打天下</h3>\n<p>MoDM 的模型池由多个不同参数规模的扩散/流匹配骨干组成，档位之间的隐藏维度、注意力头数、层数都不同。这意味着同一套手写 kernel 在小档位上可能受 launch 开销与尾效应支配，在大档位上则受 MMA 吞吐与 TMEM 容量支配。工程上必须按档位分别选择 kernel 形态：小档位（隐藏维窄、批小）优先走融合度高的轻量 kernel，把 LayerNorm、残差、SiLU 门控融进一个 kernel 以减少 HBM 往返；大档位则必须让矩阵乘走 tcgen05 路径，把权重驻留在 TMEM 附近的共享内存层级里，避免每步都从 HBM 重读。</p>\n<p>代价体现在两个方向。小档位上，一次 DiT block 的算力可能只有几十微秒量级，kernel launch 与同步的固定开销占比上升，融合是唯一出路；大档位上，单次 MMA 的算术强度足够高，但权重与激活的字节数随隐藏维平方增长，HBM 带宽成为瓶颈。用 roofline 表达档位 k 的单步代价：</p>\n<div class=\"formula\">$$T_k \\approx \\max\\!\\left(\\frac{F_k}{\\pi_k^{\\text{MMA}}},\\ \\frac{B_k}{\\beta_{\\text{HBM}}}\\right) + \\tau_{\\text{launch}}$$</div>\n<p>其中 $F_k$ 为该档位单步浮点运算量，$\\pi_k^{\\text{MMA}}$ 是该档位可达的 Tensor Core 吞吐，$B_k$ 是单步必须搬运的字节数（权重 + 激活 + 中间潜变量），$\\beta_{\\text{HBM}}$ 是 HBM 带宽，$\\tau_{\\text{launch}}$ 是 kernel 启动与同步的固定开销。小档位落在 $\\tau_{\\text{launch}}$ 主导区，大档位落在 $\\max$ 的两项之一。MoDM 的路由把请求导向不同 $k$，等于让每个请求落在不同的 roofline 区段，因此 kernel 库必须按档位预编译并做 autotune，而不是全局一套配置。</p>\n<p>具体例子：最小档位若隐藏维只有大档位的一半，其注意力矩阵乘的 N 维不足以填满一个 tcgen05 MMA 指令的 tile，此时强行用大档位的 MMA 形状会浪费一半的 Tensor Core 通道；正确做法是缩小 tile 并提高批内请求数，用批维把 N 填满。这正是档位内批合并与 kernel 形状选择必须联合调优的原因。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-15\">十五 · 数据类型：FP16/BF16 是基线，FP8 与 NVFP4 是档位差异化手段</h3>\n<p>MoDM 论文未给出量化方案，但框架本身允许各档位独立选择精度。工程判断是：小档位用 BF16 保质量下限（小模型本身容量有限，量化误差更难被容量吸收），大档位用 FP8 甚至 NVFP4 换吞吐与显存。BF16 与 FP16 的差别在于指数位宽：BF16 的动态范围与 FP32 同级，扩散采样中潜变量幅值跨步变化大，BF16 不易溢出；FP16 尾数多三位，在幅值稳定的注意力累加里精度更好。选择依据是张量的动态范围而非习惯。</p>\n<p>FP8 有两种布局：E4M3 用于权重与激活，E5M2 用于梯度类高动态范围量（推理中少见）。FP8 的关键是 scaling：每个 tensor 或每个 block 需要一个缩放因子把值域映射到 E4M3 的可表示区间，缩放因子本身用 FP32 保存。NVFP4 进一步把尾数压到 4 位，必须配 block-wise 缩放（每若干元素一个 FP8 或 FP16 缩放因子）与两级缩放结构，否则量化步长会吞掉扩散中间激活的细节。量化误差可写成：</p>\n<div class=\"formula\">$$\\epsilon_{\\text{quant}} \\approx \\frac{\\Delta^2}{12},\\quad \\Delta = \\frac{\\max|v| - \\min|v|}{2^{b}-1}$$</div>\n<p>$\\Delta$ 是量化步长，$b$ 是位宽，$\\epsilon_{\\text{quant}}$ 是均匀量化下的均方误差近似。位宽从 16 降到 8，$\\Delta$ 缩小为 1/256 量级的变化需要靠缩放因子重新对齐值域；降到 4 位时 $\\Delta$ 放大 16 倍，必须靠 block-wise 缩放把局部值域压窄，否则误差按上式平方增长。这就是 NVFP4 必须绑定 block scaling 而不能全局一个 scale 的原因。</p>\n<p>代价：FP8 把权重字节数减半，直接缓解大档位的 HBM 带宽压力，但引入缩放因子的额外读写与反量化指令；NVFP4 把权重压到 1/4，显存驻留成本显著下降——这对 MoDM 的多档位常驻是直接利好，因为档位数量增加会线性抬升显存驻留，量化是唯一能把档位池塞进单卡的手段之一。但 4 位量化的误差在 VAE 解码前的最后几步潜变量上最敏感，通常保留最后一两个 step 或 VAE 输入为高精度。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-16\">十六 · 累加精度与误差传播：MMA 内部是 FP32，跨步是另一回事</h3>\n<p>Tensor Core 的输入可以是 FP8 或 NVFP4，但累加器通常是 FP32。这意味着单次 MMA 内部的舍入误差可控，真正的误差来自跨 step 的潜变量更新：扩散/流匹配的每步都是 $x_{t-1} = f(x_t)$，量化误差在步间累积并被非线性放大。把单步误差记为 $\\epsilon_t$，N 步后的误差上界可写成：</p>\n<div class=\"formula\">$$\\|\\epsilon_N\\| \\le \\sum_{t=1}^{N} \\|J_t\\|^{N-t}\\,\\|\\epsilon_t\\|$$</div>\n<p>$J_t$ 是第 $t$ 步更新对输入的雅可比，$\\|J_t\\|$ 是其算子范数。若 $\\|J_t\\|&gt;1$，早期步的误差被指数放大；若小于 1，误差被衰减。扩散采样器在低噪声段雅可比范数通常较小，高噪声段较大，因此量化误差最危险的位置是高噪声段的前几步，而不是最后几步。这与“最后几步敏感”的直觉相反，工程上应以雅可比谱范数的经验测量决定哪几步保留高精度，而不是拍脑袋。</p>\n<p>MoDM 的档位配置步数不同：小档位步数少，误差累积项数少但每步的模型容量小、雅可比可能更陡；大档位步数多，累积项多但每步更平滑。因此同一量化位宽在不同档位上的误差表现不可直接迁移，必须按档位分别校准。代价是校准工作量随档位数线性增长，这是多档位服务化的隐性成本。</p>\n<p>具体例子：CFG 正负分支合并为一个批后，等效批大小翻倍，负分支的条件嵌入与正分支不同，若两者共用同一个 per-tensor 缩放因子，负分支的激活值域可能被正分支主导而量化粗糙。正确做法是按分支或按 block 分别统计缩放因子，代价是缩放因子数量翻倍、反量化开销上升。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 如何改变档位设计</h3>\n<p>第五代 Tensor Core 的 tcgen05 指令把矩阵乘的累加器放在 TMEM（Tensor Memory）而不是寄存器堆。TMEM 是每个 SM 私有的、容量有限的片上存储，专门服务 MMA 累加。好处是累加器不再占用寄存器，寄存器压力释放后可以支撑更大的 tile 与更深的流水；代价是 TMEM 容量成为硬约束——一个 tile 的累加器尺寸必须塞进 TMEM，否则要拆成多次 MMA 并回写。对 MoDM 的大档位，隐藏维大意味着注意力输出的 N 维大，TMEM 容量决定了单次 MMA 能覆盖多宽的输出，进而决定是否需要 K 维拆分。</p>\n<p>2-SM MMA 让两个 SM 协作完成一次 MMA，把有效 tile 尺寸翻倍。它适合大档位的大矩阵乘：单 SM 的 TMEM 装不下的 tile 可以由 2-SM 协作分摊，代价是跨 SM 的同步与数据交换，要求两个 SM 的调度对齐。小档位的矩阵乘尺寸不足以喂饱 2-SM，强行使用会因同步开销而变慢。因此档位与 MMA 形态的匹配是：小档位单 SM、小 tile、高融合；大档位 2-SM、大 tile、深流水。</p>\n<p>把 TMEM 约束写成可行性条件：</p>\n<div class=\"formula\">$$M_{\\text{tile}}\\cdot N_{\\text{tile}}\\cdot 4\\ \\text{bytes} \\le C_{\\text{TMEM}},\\quad \\text{否则拆分为}\\ \\lceil N_{\\text{tile}}/N_{\\max}\\rceil\\ \\text{次 MMA}$$</div>\n<p>$M_{\\text{tile}},N_{\\text{tile}}$ 是 MMA 的输出 tile 尺寸，系数 4 对应 FP32 累加器字节数，$C_{\\text{TMEM}}$ 是单 SM（或 2-SM 协作下合计）的 TMEM 容量。当输出 tile 超出容量，必须沿 N 维拆分，拆分会增加累加器回写与流水气泡，直接抬高单步延迟。MoDM 的档位若隐藏维恰好落在 TMEM 容量的临界点附近，性能会出现台阶式跳变，autotune 必须覆盖这个边界。</p>\n<p>代价层面：TMEM 驻留减少了寄存器溢出到 local memory 的流量，等价于降低 HBM 与 L1 的往返；但 TMEM 容量固定，档位数量增加意味着每个档位都要独立做 tile 形状调优，编译与验证成本上升。功耗上，2-SM MMA 把两个 SM 的 Tensor Core 同时拉满，瞬时功耗高于单 SM，机架级供电与散热需按峰值而非均值规划。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-18\">十八 · 公式逐项落地：从路由目标到 kernel 配置的映射</h3>\n<p>MoDM 的路由目标 $\\hat{k}=\\arg\\min_k (s(x)/c_k + \\lambda q_k)$ 中的 $c_k$ 是单位算力代价，它在 kernel 层面不是抽象常数，而是档位 k 的单步实测延迟与单步 FLOPs 的比值。工程上应把 $c_k$ 标定为该档位在当前批大小与精度配置下的实测值，而不是理论峰值倒数。因为小档位受 launch 开销支配、大档位受带宽或 TMEM 拆分支配，理论峰值与实际可达吞吐的差距随档位变化，用理论值会让路由系统性偏向某一档。</p>\n<p>把 $c_k$ 展开：</p>\n<div class=\"formula\">$$c_k = \\frac{T_k^{\\text{step}}(b_k, \\text{dtype}_k)}{F_k^{\\text{step}}},\\quad b_k = \\text{batch size at tier } k$$</div>\n<p>$T_k^{\\text{step}}$ 是档位 k 在批大小 $b_k$ 与数据类型 $\\text{dtype}_k$ 下的实测单步延迟，$F_k^{\\text{step}}$ 是单步 FLOPs。批大小进入分母之外还影响 $T_k^{\\text{step}}$ 本身：批越大，MMA 的 M 维越满，单位 FLOPs 的延迟越低，但显存与 TMEM 压力上升。因此 $c_k$ 是批大小的函数，路由与批调度必须联合求解，而不是先路由再定批。</p>\n<p>具体例子：若大档位在批大小为 1 时因 M 维填不满而 $c_k$ 偏高，路由器会把请求推向小档位；但当同档位请求积累到一定批大小，$c_k$ 下降，路由应回摆。这要求路由器读取各档位当前批大小而非仅队列长度，$\\lambda q_k$ 项只捕捉排队，不捕捉批效率。工程上可在 $c_k$ 标定表里按批大小分档查表，把批效率纳入路由代价。</p>\n<p>误差与精度的联合代价也要进路由：若某档位启用了 NVFP4，其 $c_k$ 更低但质量下限也低，$s(x)$ 高的请求不应被低价吸引。做法是给每个档位设一个质量下限约束，路由目标在满足质量约束的档位集合内取最小代价，把量化带来的质量回退挡在路由层之外，而不是等误路由发生后再补救。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-19\">十九 · 工程判断：精度与 kernel 配置应随档位冻结，而非全局统一</h3>\n<p>MoDM 的多档位结构决定了一件事：kernel 形状、数据类型、累加策略、TMEM tile 划分这四项必须按档位冻结成一组配置，在部署期一次性 autotune 并写入档位元数据。运行时只做查表与批合并，不做在线重编译。原因是扩散采样的单步延迟对 kernel 配置极其敏感，在线切换配置会引入编译与同步抖动，直接破坏尾延迟。档位元数据里应记录：该档位的 dtype、缩放因子布局、MMA tile 形状、是否启用 2-SM、TMEM 拆分次数、以及对应的 $c_k$ 标定表。</p>\n<p>显存侧，档位数量增加线性抬升权重驻留，量化是唯一解。把大档位权重压到 FP8、小档位保留 BF16，可以在不牺牲小档位质量下限的前提下把大档位的显存占用减半，从而允许更多档位常驻。VAE 解码的共享批合并对精度更敏感，VAE 通常保留 BF16 或 FP16，不随 DiT 档位一起量化——解码阶段的误差会直接体现在像素上，且没有后续 step 来平滑。</p>\n<p>最后落在具体机制上：档位 k 的 kernel 配置应以其 TMEM 容量与实测 $c_k$ 为约束求解 tile 形状，使 $\\max(F_k/\\pi_k, B_k/\\beta)$ 最小化，并把结果与 dtype、缩放布局一起冻结进档位元数据；路由层只读这份元数据做代价比较，批调度层按冻结的批上限合并请求。这样精度选择、kernel 形状与路由代价三者共享同一份标定，避免了“路由按理论峰值算、kernel 按另一套 tile 跑”的错配，这是 MoDM 在 Blackwell 上把多档位池跑稳的最小工程闭环。</p>\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-20\">二十 · 显存账本的三个账户：权重、激活、KV 式中间缓存</h3>\n<p>MoDM 的显存问题不是\"一个模型装不装得下\"，而是\"K 个档位同时驻留时装不装得下\"。把单卡显存拆成三个账户来记账，是唯一能落地做容量规划的方式：权重账户、激活账户、KV 式中间缓存账户。权重账户是静态的，按档位线性叠加；激活账户随批大小与分辨率增长，是采样前向的瞬时开销；KV 式中间缓存账户在扩散服务里对应的是每步迭代驻留的潜变量、注意力中间张量与 CFG 分支副本，它不是 LLM 那种自回归增长的 KV，而是\"步内产生、步间复用、请求结束即释放\"的短生命周期缓存。三个账户的回收时机完全不同：权重永不释放，激活随前向结束释放，中间缓存随请求完成释放。MoDM 的\"各档位独立维护显存与 KV 式中间缓存\"这句话，工程含义就是三个账户按档位分区记账，档位之间不共享中间缓存，因此档位数量直接抬升常驻水位。</p>\n<p>记账公式可以写成可复算的形式。设档位 k 的参数量为 \\(P_k\\)、权重每参比特数为 \\(b_k\\)、单请求在该档位的中间缓存字节数为 \\(M_k(B)\\)（依赖批大小 B 与分辨率）、激活峰值字节数为 \\(A_k(B)\\)，则单卡常驻水位为：</p>\n<div class=\"formula\">$$W_{\\text{resident}}=\\sum_{k=1}^{K}\\frac{P_k\\cdot b_k}{8}+B_{\\text{slot}}\\cdot\\max_k\\big(M_k(B)+A_k(B)\\big)+W_{\\text{dec}}$$</div>\n<p>其中 \\(B_{\\text{slot}}\\) 是同时在采样的请求槽位数，\\(W_{\\text{dec}}\\) 是共享 VAE 解码器的权重与解码批激活。注意 max 取在所有档位上——因为路由是动态的，任何一个档位都可能在同一时刻被填满，容量规划必须按最坏档位算，而不是按平均档位算。这正是 MoDM 显存约束的本质：路由带来的算力节省，是用\"每个档位都要留出满槽位空间\"换来的。档位数量 K 增加时，第一项线性上升，第二项因 max 不变而基本持平，所以小档位多、大档位少的不均匀池比均匀池更省显存。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-21\">二十一 · 分页与复用：把中间缓存做成可回收的页</h3>\n<p>扩散采样与 LLM 解码的显存形态差异在于：LLM 的 KV cache 随生成长度单调增长，扩散的中间缓存随步数循环覆写，理论上只需保留当前步的潜变量与注意力工作区。但 MoDM 里有两个因素打破了这个理想：一是 CFG 正负分支合并为一个批，等效批大小翻倍，注意力工作区按 2B 计；二是档位内批合并要求不同请求在同一前向里对齐分辨率与步数，未对齐的请求必须挂起并保留其潜变量，形成\"等待中的缓存\"。因此中间缓存不能简单按单请求峰值算，要按\"活跃槽位 + 挂起槽位\"算。</p>\n<p>工程上把中间缓存按页管理：以固定大小的页（例如按潜变量空间分辨率切块）为单位分配，请求挂起时其页被标记为可回收但不立即释放，批合并时按页拼批。分页的代价是页表查找与碎片：页大小选得小则碎片少但管理开销高，选得大则批对齐容易但挂起请求浪费页。一个具体例子：潜变量为 64×64×4 通道、fp16 存储时单请求潜变量约 32KB 量级，若页大小取 64KB，则一个挂起请求至少占一页，挂起槽位多时页浪费显著；若页大小取 16KB，则一个请求跨两页，批合并时需跨页拼接，注意力 kernel 的地址计算变复杂。这个权衡没有普适最优，只能按档位分辨率与批合并频率实测。</p>\n<p>复用维度有三条：跨步复用（同请求相邻步之间潜变量原地覆写，省一次分配）、跨请求复用（同档位同分辨率的挂起请求共享页池）、跨阶段复用（采样结束的潜变量直接进入 VAE 解码批，不经过主机内存往返）。第三条对带宽最敏感：若潜变量经 PCIe 回主机再进解码，等于把采样阶段省下的 HBM 带宽又还回去。MoDM 的\"共享 VAE 解码批\"在显存账本上的意义就是把解码激活与采样缓存放在同一显存池，解码完成即整批释放。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-22\">二十二 · 压缩与卸载：权重比特数与档位驻留的取舍</h3>\n<p>权重账户的压缩直接决定 K 的上限。以 \\(b_k\\) 从 16 降到 8 再到 4，第一项按比例缩小，同样容量下可容纳的档位数量翻倍或四倍。但压缩不是免费的：低比特权重在 DiT 注意力上的数值误差会放大到图像质量，且低比特 GEMM 需要 tensor core 的对应指令支持，反量化开销会挤占带宽。对 MoDM 而言更现实的策略是\"大档位低比特、小档位高比特\"的非均匀配置——大档位参数多、常驻成本高，压缩收益最大；小档位参数少，压缩省下的显存不足以抵消质量风险。这个判断与量化条目的细节正交，此处只落在账本上：\\(b_k\\) 是每个档位独立的决策变量，不是全局常数。</p>\n<p>卸载（offload）在 MoDM 里的适用面很窄。权重卸载到主机内存意味着档位切换时要重新搬回 HBM，而路由是每请求决策、队列长度秒级变化，权重往返的延迟会直接打在尾延迟上。可行的卸载对象是\"低频档位\"：按路由命中率统计，把命中率低于阈值的档位权重放在主机侧，仅在队列积压到该档位时预取。代价是预取窗口内的请求排队，收益是常驻水位下降。中间缓存的卸载则更危险：挂起请求的潜变量若卸载到主机，恢复时要重新走一遍注意力工作区分配，且 PCIe 带宽远低于 HBM，批量挂起时恢复延迟会累积。工程判断是：权重可选择性卸载，中间缓存不卸载，激活不卸载。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-23\">二十三 · 带宽瓶颈的位置：CFG 合并与 VAE 解码</h3>\n<p>MoDM 的带宽瓶颈不在权重读取，而在两个被合并放大的环节。第一是 CFG 正负分支合并：等效批大小翻倍意味着单次前向的激活读写翻倍，注意力矩阵的读写量按批大小线性增长，而前向次数减半只节省了权重读取与 kernel 启动开销。当批大小已经较大时，合并 CFG 的收益从\"省算力\"转为\"省启动开销\"，带宽反而成为约束——激活的写回与读回在 HBM 上往返，等效批翻倍就是往返量翻倍。第二是 VAE 解码：解码阶段的上采样与卷积对激活的读写量远大于 DiT 单步，共享解码批把多个请求拼在一起摊薄了权重读取，但解码激活的峰值随批大小线性上升，是显存账本里 \\(W_{\\text{dec}}\\) 的主要构成。</p>\n<p>定量地看，单步前向的 HBM 流量近似为权重流量加激活流量：</p>\n<div class=\"formula\">$$\\text{Traffic}_{\\text{step}}\\approx \\underbrace{\\frac{P_k b_k}{8}}_{\\text{权重读}}+\\underbrace{2B\\cdot H\\cdot W\\cdot C\\cdot d}_{\\text{激活读写}}\\cdot n_{\\text{layer}}$$</div>\n<p>其中 \\(d\\) 为每元素字节数，\\(n_{\\text{layer}}\\) 为层数。第一项与批大小无关，第二项线性于批大小。存在一个批大小临界点，超过它激活流量主导，此时继续加批只增带宽不增吞吐效率。MoDM 的档位内批合并必须在这个临界点之下做，否则合并的收益被带宽吃掉。这个临界点随档位规模变化：小档位 \\(P_k\\) 小，临界点来得早；大档位 \\(P_k\\) 大，临界点来得晚。所以\"档位内批大小按档位分别设定\"不是调度偏好，是带宽账本的硬约束。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-24\">二十四 · 可复算的显存预算：一个具体算例</h3>\n<p>下面给一个只用符号与给定事实、不引入编造数字的预算框架，读者可代入自己硬件的 HBM 容量复算。设单卡 HBM 容量为 \\(C_{\\text{HBM}}\\)，档位数为 K，第 k 档参数量 \\(P_k\\)、权重比特 \\(b_k\\)，共享 VAE 权重 \\(P_{\\text{VAE}}\\)、比特 \\(b_{\\text{VAE}}\\)，槽位数 \\(B_{\\text{slot}}\\)，单请求中间缓存与激活峰值之和的最大值 \\(M_{\\max}\\)，则可行条件为：</p>\n<div class=\"formula\">$$\\sum_{k=1}^{K}\\frac{P_k b_k}{8}+\\frac{P_{\\text{VAE}}b_{\\text{VAE}}}{8}+B_{\\text{slot}}\\cdot M_{\\max}\\le \\alpha\\, C_{\\text{HBM}}$$</div>\n<p>其中 \\(\\alpha\\) 是安全系数，需扣除框架运行时、通信缓冲与碎片，工程上取小于 1 的值。这个不等式给出三条可操作的判断。其一，K 的上限由第一项决定：给定 \\(P_k\\) 分布与 \\(b_k\\)，可解出最大 K，这就是\"档位过多则显存与调度开销上升\"的定量来源。其二，\\(B_{\\text{slot}}\\) 的上限由剩余容量除以 \\(M_{\\max}\\) 决定，而 \\(M_{\\max}\\) 取最坏档位，所以大档位的分辨率与批大小直接压低全局槽位数——这是 MoDM 里最容易被忽视的耦合：大档位的显存开销会挤占小档位的并发槽位。其三，\\(\\alpha\\) 的取值与是否做权重卸载相关：若低频档位卸载到主机，第一项中对应项可移出不等式，但需在调度侧保证预取窗口。</p>\n<p>一个具体例子走一遍流程：假设池内三档，参数量比为 1:4:16，权重统一为某比特数，则第一项按 21 份计；若把最大档位比特数减半，第一项降为 13 份，省出的 8 份容量可用于增加槽位或增加一个中档位。反过来，若把最大档位分辨率提高一档，\\(M_{\\max}\\) 上升，槽位数按比例下降，吞吐可能不升反降。这就是为什么 MoDM 的档位映射校准必须联合考虑质量—步数曲线与显存预算，而不能只按难度分数切分。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-25\">二十五 · 账本与调度的接口：释放时机决定尾延迟</h3>\n<p>显存账本最终要落到调度器的释放时机上。MoDM 的流水线是\"采样结束→进入共享解码批→解码完成→释放显存与中间缓存→更新队列长度\"。这里有两个接口细节决定尾延迟。第一，解码批的入队等待：若解码批按固定批大小攒批，先完成的请求要等后完成的请求凑批，其显存被占住的时间被拉长，等效槽位数下降。解法是设解码批的超时上限，超时即用当前批解码，代价是解码效率下降。第二，释放与路由的时序：队列长度在释放后才更新，路由器看到的是滞后信息，高峰时会把请求导向一个实际已满的档位。解法是在路由目标函数里用\"在途请求数\"而非\"已完成队列长度\"作为 \\(q_k\\)，把已分配但未释放的槽位计入负载。</p>\n<p>把这两点合起来看，MoDM 的显存约束不是静态容量问题，而是\"容量×释放时机×路由信息新鲜度\"的三元耦合。容量决定 K 与槽位上限，释放时机决定有效槽位数，路由信息新鲜度决定槽位是否被错配。工程上可做的判断是：优先保证释放时机的确定性（解码超时、缓存即释放），再用在途计数修正路由，最后才考虑增加档位或压缩比特——因为前两者不增加显存水位，后者直接抬升常驻成本。这也解释了论文消融里\"档位过少收益有限、过多则显存与调度开销上升\"的定性结论：档位数量的边际收益被释放时机与路由滞后吃掉，而不是被权重本身吃掉。</p>\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-26\">二十六 · 连续批处理在扩散采样循环里的落点</h3>\n<p>自回归推理的连续批处理（continuous batching）之所以成立，是因为解码是逐 token 的迭代，序列在任意时刻可以加入或退出批次。扩散采样在形式上与之同构：采样器本身就是固定步数的迭代循环，每一步对潜变量做一次完整的 DiT 前向。MoDM 把这一同构关系直接拿来用——档位内的批不是按“请求集合”静态划分，而是按“采样步”动态维护。一个请求在第 t 步进入批次，只承诺参与第 t 步及之后的前向，直到其步数预算耗尽；新到达的请求在下一个采样步边界插入，已完成的请求在步边界退出。批的成员在每个 step boundary 重新计算，而不是每个请求生命周期内固定。</p>\n<p>关键机制在于步边界对齐：由于同一档位内所有请求共享同一采样器配置（步数、CFG 策略、噪声调度），批合并只在步维度上做，不需要像 LLM 那样处理变长序列的 padding 问题。代价是批内请求的剩余步数不同，早完成的请求会留下空洞。MoDM 的处理是把空洞用同档位新到达请求即时填充，填充失败时允许批规模暂时收缩。这带来一个直接的吞吐代价：批规模波动导致 DiT 前向的矩阵乘维度在相邻步之间变化，tcgen05 MMA 的 tile 对齐效率下降，尤其在批规模跌破 MMA tile 边界时，算力利用率出现台阶式损失。</p>\n<p>设档位 k 的批规模为 <span class=\"inline-math\">b<sub>k</sub>(t)</span>，单步前向代价近似正比于批规模与模型参数量，则档位内单步时延可写成：</p>\n<div class=\"formula\">$$T_{\\text{step},k}(t)=\\alpha_k+\\beta_k\\cdot b_k(t)+\\gamma_k\\cdot \\mathbb{1}[b_k(t)\\bmod M\\neq 0]$$</div>\n<p>其中 <span class=\"inline-math\">α<sub>k</sub></span> 是固定启动开销（kernel launch、权重读取），<span class=\"inline-math\">β<sub>k</sub></span> 是单位请求的算力项，<span class=\"inline-math\">γ<sub>k</sub></span> 是批规模未对齐 MMA tile 宽度 <span class=\"inline-math\">M</span> 时的惩罚项。这个式子说明连续批处理在扩散里的收益不是单调的：批越大，<span class=\"inline-math\">α<sub>k</sub></span> 摊薄越好，但 <span class=\"inline-math\">b<sub>k</sub>(t)</span> 的抖动会把 <span class=\"inline-math\">γ<sub>k</sub></span> 项反复触发。工程判断是给每个档位设一个最小批规模下限，低于下限时宁可等待一个步边界再合并，也不让批规模跌进非对齐区间。</p>\n<p>具体例子：小档位模型步数预算为 8 步，大档位为 24 步。若一个简单请求在小档位第 3 步完成，其占用的批槽位在第 4 步被新请求填充；若此时队列为空，小档位批规模从 8 掉到 7，恰好跨过 tile 对齐边界，则该步的实际算力利用率下降，但端到端时延未必变差——因为该请求已经完成。这说明连续批处理在扩散服务里优化的目标是吞吐而非单请求延迟，二者在批规模收缩点上是分离的。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-27\">二十七 · Chunked prefill 的扩散对应物：分步预填与潜变量分段</h3>\n<p>LLM 的 chunked prefill 把长 prompt 的预填切成若干块，与解码请求混批，避免长预填阻塞解码的尾延迟。扩散没有“预填”这个独立阶段，但有等价物：初始潜变量的构造、文本编码器的条件注入、以及 CFG 双分支的首次前向。MoDM 把这些统称为“条件准备阶段”，并对它做分块处理——文本编码器输出与初始噪声拼接不一次性完成，而是按潜变量空间分块注入，使条件准备与采样步的前向可以交错执行。</p>\n<p>伪代码思路如下：请求到达后，难度评估器给出 <span class=\"inline-math\">s(x)</span>，路由器选出档位 <span class=\"inline-math\">k</span>。条件准备被切成 <span class=\"inline-math\">C</span> 个 chunk，每个 chunk 完成即挂到该档位的待采样队列上，而不是等全部条件就绪才入队。这样做的直接收益是：条件准备阶段的显存占用从“整张潜变量 + 完整条件张量”降为“一个 chunk 的潜变量切片 + 条件切片”，峰值显存下降，使单卡能同时驻留更多档位的活跃请求。</p>\n<p>代价在带宽侧。分块注入意味着条件张量被多次读写，而不是一次大传输。在 Blackwell 的 HBM 带宽约束下，chunk 数量 <span class=\"inline-math\">C</span> 增大时，条件张量的重复读取带宽开销近似线性上升：</p>\n<div class=\"formula\">$$B_{\\text{cond}}\\approx C\\cdot \\big(|z_0|+|c_{\\text{text}}|\\big)\\cdot f_{\\text{read}}$$</div>\n<p>其中 <span class=\"inline-math\">|z<sub>0</sub>|</span> 是初始潜变量大小，<span class=\"inline-math\">|c<sub>text</sub>|</span> 是文本条件大小，<span class=\"inline-math\">f<sub>read</sub></span> 是单位字节的读取频率因子。工程上 <span class=\"inline-math\">C</span> 的取值要在峰值显存与带宽之间取平衡点：<span class=\"inline-math\">C</span> 太小则显存峰值高、并发受限；<span class=\"inline-math\">C</span> 太大则条件张量反复搬运，DiT 注意力层的有效带宽被挤占。MoDM 的档位配置里，小档位倾向用较大的 <span class=\"inline-math\">C</span>（模型小、显存紧），大档位用较小的 <span class=\"inline-math\">C</span>（模型大、带宽相对充裕），这是按档位而非全局统一的参数。</p>\n<p>具体例子：一个带长提示词的请求进入大档位，条件准备被切成 4 个 chunk，每个 chunk 完成后立即参与首个采样步的前向；与此同时，同档位另一个已完成条件准备的请求在等待批合并。两者在第 2 个采样步边界合并，条件准备的尾延迟被采样步的前向掩盖，而不是串行叠加在端到端时延上。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-28\">二十八 · 优先级、抢占与档位队列的联合决策</h3>\n<p>MoDM 的路由目标函数 <span class=\"inline-math\">s(x)/c<sub>k</sub> + λ·q<sub>k</sub></span> 已经把队列长度写进了决策，但队列长度只是标量，不区分请求的优先级。在服务化场景里，尾延迟往往由少数高优先级或长步数请求主导，单纯按队列长度均衡会把它们推到低负载档位，反而拉长其完成时间。MoDM 在档位内引入两级队列：高优先级队列与普通队列，批合并时优先从高优先级队列取请求填充空洞，普通队列请求只在批规模未达上限时补位。</p>\n<p>抢占机制在扩散里的实现比 LLM 简单，因为扩散请求没有 KV cache 的跨步增长问题，但有潜变量中间态的驻留。当一个高优先级请求到达且目标档位批已满时，系统可以抢占一个普通队列请求：被抢占请求的当前潜变量与剩余步数被写回显存（或主机内存），释放其批槽位；高优先级请求插入当前步。被抢占请求在后续步边界重新入队，从被中断的步继续采样，而不是从头开始。这要求潜变量中间态可序列化，代价是一次显存写回加一次读回。</p>\n<p>抢占的代价可以量化为：设被抢占请求的潜变量大小为 <span class=\"inline-math\">|z<sub>t</sub>|</span>，写回与读回各一次，则单次抢占的额外带宽开销为 <span class=\"inline-math\">2·|z<sub>t</sub>|</span>，加上调度决策的固定开销。若抢占频率过高，这部分开销会侵蚀连续批处理带来的吞吐收益。工程判断是给抢占设一个冷却窗口：同一请求在 <span class=\"inline-math\">W</span> 个步内不被重复抢占，<span class=\"inline-math\">W</span> 的取值与档位步数预算挂钩，小档位 <span class=\"inline-math\">W</span> 小（步数少、抢占窗口短），大档位 <span class=\"inline-math\">W</span> 大。</p>\n<p>具体例子：大档位批规模已满，一个高优先级请求到达，路由器判定其难度分数适合大档位。系统抢占一个已采样 10 步、剩余 14 步的普通请求，写回其潜变量；高优先级请求插入当前步。被抢占请求在下一个步边界重新入队，从第 11 步继续。端到端上，高优先级请求的尾延迟被压缩，普通请求的完成时间延后但总步数不变——这是用吞吐换尾延迟的典型取舍。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-29\">二十九 · 分离式预填/解码在扩散服务里的映射</h3>\n<p>LLM 的分离式预填/解码（disaggregated prefill/decode）把计算密集的预填与带宽密集的解码放到不同资源池，避免二者互相干扰。扩散的对应划分不是按阶段，而是按资源特征：条件准备与高步数采样是计算密集的，VAE 解码与低步数采样是带宽与显存密集的。MoDM 的流水线里，采样执行与 VAE 解码本来就是分离的两段，但默认在同一档位内串行。分离式部署把 VAE 解码抽出来做成共享解码池，多个档位的采样结果统一送入解码池批合并。</p>\n<p>这一分离的收益在显存侧最直接：采样阶段占用的 DiT 权重与中间潜变量，与解码阶段占用的 VAE 权重不再同时驻留于同一批显存预算内。设档位 k 的 DiT 权重显存为 <span class=\"inline-math\">M<sub>DiT,k</sub></span>，VAE 权重为 <span class=\"inline-math\">M<sub>VAE</sub></span>，分离前单卡需同时容纳二者，分离后解码池独立持有 <span class=\"inline-math\">M<sub>VAE</sub></span>，采样侧只保留 <span class=\"inline-math\">M<sub>DiT,k</sub></span> 与活跃潜变量。对于多档位模型池，这意味着采样侧的显存驻留从 <span class=\"inline-math\">Σ<sub>k</sub>M<sub>DiT,k</sub> + M<sub>VAE</sub></span> 变为 <span class=\"inline-math\">Σ<sub>k</sub>M<sub>DiT,k</sub></span> 加解码池的独立预算，档位数量增加时显存压力不再与 VAE 叠加。</p>\n<p>代价在通信与调度。采样结果从采样侧传到解码池需要一次潜变量传输，跨卡时走 NVLink 5，跨节点走 NIXL 之类的传输层。传输延迟与潜变量大小成正比，且解码池的批合并需要等待多个档位的采样结果到齐，引入额外的排队延迟。工程上，解码池的批合并窗口要设上限：窗口内到齐的潜变量立即合并解码，未到齐的请求不阻塞已到齐的批次。这与 LLM 分离式部署里解码池的调度逻辑同构，区别在于扩散的潜变量是定长的，批合并的 padding 开销为零，合并效率比变长序列更高。</p>\n<p>具体例子：小档位完成 8 步采样后，潜变量送入共享解码池；大档位完成 24 步采样后同样送入。解码池在一个窗口内收到来自两个档位的潜变量，合并成一个解码批一次 VAE 前向，摊薄了解码阶段单位请求的显存与带宽占用。若窗口内只有小档位的结果到齐，解码池立即解码小档位批次，不等大档位——这避免了慢请求拖累快请求的尾延迟。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-30\">三十 · 尾延迟的压制：从队列权重到步边界调度</h3>\n<p>尾延迟在扩散服务里有两个来源：队列排队与批内慢请求。队列排队的压制靠路由器的 λ 权重，把请求导向低负载档位；但 λ 是静态校准参数，负载突变时响应滞后。MoDM 的补充机制是步边界重路由：请求在每个步边界重新评估一次是否应留在当前档位，若当前档位队列长度超过阈值且存在低负载档位，则允许迁移。迁移的代价是潜变量跨档位传输加目标档位的批合并等待，因此只对剩余步数较多的请求开放迁移，剩余步数少的请求迁移收益不足以抵消传输开销。</p>\n<p>批内慢请求的压制靠批规模上限与超时。连续批处理允许批规模动态变化，但批内最慢请求决定该批的完成时间。MoDM 给每个档位设批规模上限 <span class=\"inline-math\">B<sub>max,k</sub></span>，并在批合并时优先选择剩余步数相近的请求，减少批内步数离散度。设批内请求剩余步数的方差为 <span class=\"inline-math\">σ<sup>2</sup><sub>steps</sub></span>，批完成时间近似为最大剩余步数乘以单步时延，方差越大，批内快请求的空等时间越长：</p>\n<div class=\"formula\">$$T_{\\text{batch}}\\approx \\max_{i\\in\\text{batch}} r_i \\cdot T_{\\text{step},k},\\quad \\text{空等代价}\\propto \\sigma^2_{\\text{steps}}$$</div>\n<p>其中 <span class=\"inline-math\">r<sub>i</sub></span> 是请求 <span class=\"inline-math\">i</span> 的剩余步数。按剩余步数分桶合并是压制这一代价的直接手段：同桶内请求步数接近，批完成时间的离散度低，快请求不必等慢请求太多步。分桶的代价是批规模可能不足以填满 MMA tile，需要在分桶粒度与批规模之间取平衡。</p>\n<p>具体例子：大档位队列里同时存在剩余 20 步与剩余 3 步的请求。若不分桶合并，剩余 3 步的请求要等 20 步的请求完成才能释放批槽位，空等 17 步；分桶后，剩余 3 步的请求进入短步数桶，在 3 步内完成并释放槽位，尾延迟显著下降。代价是短步数桶的批规模小，单步算力利用率低，但短步数桶的总步数少，总算力损失有限。</p>\n<p>时延与吞吐的取舍最终落在档位配置上：小档位步数少、批规模可以开大，吞吐优先；大档位步数多、批规模受显存与批内离散度约束，时延优先。MoDM 的档位划分本身就是这一取舍的载体——不是全局一套批调度参数，而是每个档位独立校准批规模上限、分桶粒度与抢占冷却窗口。工程判断是：档位数量增加会线性抬升显存驻留与调度复杂度，档位过少则路由收益有限，校准点应落在“档位数量刚好覆盖负载难度分布的尾部”而非均匀切分。</p>\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-31\">三十一 · 档位即并行域：MoDM 的切分边界在哪</h3>\n<p>MoDM 的并行问题与单一大模型服务有本质区别：它的并行粒度首先由“档位”决定，而不是由张量形状决定。模型池里每个档位是一个独立的扩散/流匹配骨干，档位之间不共享权重、不共享中间缓存，因此档位间天然是数据并行（DP）关系——每个档位各自持有一份完整权重、各自消费路由过来的请求。真正需要在档位内部做切分的是 TP/EP/PP：小档位可能单卡即可容纳，大档位才需要跨卡张量并行或专家并行。这带来一个工程判断：并行拓扑必须按档位分别配置，而不是全池统一。若把最大档位的 TP 度套到最小档位上，小档位的通信量会白白放大；若按最小档位配置，大档位又放不下。合理的做法是让每个档位声明自己的 (TP, EP, PP) 三元组，路由器在做队列决策时把“该档位当前可用的并行副本数”作为隐含容量约束，这与前文路由目标里的 q_k 是同一件事的两个侧面。</p>\n<p>以 B200 单卡 192GB HBM3e 为参照，一个中等规模 DiT 骨干在 FP8 下权重加激活加 CFG 双分支的中间潜变量，单卡可以承载；但大档位叠加更长步数与更大分辨率时，单卡显存会被中间缓存挤爆，此时必须上 TP=2 或 TP=4。切分维度上，DiT 的注意力与 MLP 都是天然的列/行并行对象，tcgen05 的 2-SM MMA 又要求配对的两个 SM 落在同一 CTA pair 上，因此 TP 组最好落在同一 GPC 内，让 2-SM MMA 的配对不跨 NVLink。这是一个具体的放置约束：TP 通信走的是片内 SM-to-SM 与共享内存路径，不该被当成跨卡集合通信来规划。</p>\n<div class=\"formula\">$$\\text{每档位副本数}\\ n_k=\\left\\lfloor \\frac{M_{\\text{pool}}}{W_k + A_k(b_k)}\\right\\rfloor,\\quad \\sum_k n_k W_k \\le M_{\\text{pool}}$$</div>\n<p>这里 W_k 是档位 k 的权重显存，A_k(b_k) 是该档位在批大小 b_k 下的激活与中间缓存，M_pool 是池子可用的总显存。这个式子说明档位数量与每档副本数是零和的：档位越多，单档能开的并行副本越少，DP 度越低，吞吐弹性越差。这正是论文消融里“档位过多则显存与调度开销上升”的定量来源，也是并行规划的第一条硬约束。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-32\">三十二 · NVLink 5 与 NVSwitch：All-Reduce 什么时候真的便宜</h3>\n<p>GB200/GB300 NVL72 的机柜内互连是 NVLink 5 加 NVSwitch，72 个 GPU 处于同一非阻塞域内，任意两卡之间是一跳。这改变了对 All-Reduce 的直觉：在 NVL72 内做 TP 的 All-Reduce，带宽不再是主要矛盾，延迟与同步开销才是。一个 TP=8 的 DiT 层，每层两次 All-Reduce（注意力输出一次、MLP 下投影一次），若层数深、步数多，集合通信的发起次数会线性堆叠。工程上的对策不是加大 chunk，而是把多个小 All-Reduce 合并成一次、或者用 reduce-scatter + all-gather 融合掉一次往返。对 MoDM 而言，更关键的是：小档位根本不该开 TP。单卡能放下的档位开 TP=2 只会把每层两次本地归约变成两次跨卡归约，延迟上升而吞吐不升，这是纯粹的负收益。</p>\n<p>NVSwitch 的全连接拓扑还带来一个副作用：All-to-All 在 NVL72 内是可行且相对廉价的，这使 EP 成为大档位 MoE 化骨干的合理选择。但扩散骨干的专家并行有个特殊性——每个去噪步都要做一次 token 到专家的分发与回收，步数固定且多，All-to-All 的次数等于步数乘以层数。假设 30 步、每步 24 层、每层一次 All-to-All，就是 720 次集合通信。即便单次只有几十微秒，累计也在毫秒到十毫秒量级，对单请求端到端时延是可见的。因此 EP 只在“专家数远超单卡容量、且批足够大能摊薄”时才划算；批小的时候 EP 的通信开销摊不薄，反而不如 TP 或干脆不切。</p>\n<table class=\"mini\"><thead><tr><th>并行方式</th><th>通信原语</th><th>在 MoDM 中的适用位置</th><th>主要代价</th></tr></thead><tbody><tr><td>DP</td><td>无（档位间独立）</td><td>档位之间、档位内副本之间</td><td>显存复制，副本数受 M_pool 限制</td></tr><tr><td>TP</td><td>All-Reduce / RS+AG</td><td>仅大档位，且同 GPC 内配对</td><td>每层每步同步，延迟随层数×步数增长</td></tr><tr><td>EP</td><td>All-to-All</td><td>大档位的 MoE 化骨干</td><td>次数 = 步数×层数，小批摊不薄</td></tr><tr><td>PP</td><td>点对点激活传递</td><td>超大档位跨节点时</td><td>流水气泡，扩散步间难重叠</td></tr></tbody></table>\n<p>PP 在扩散推理里是最不讨好的：去噪步是严格串行的，PP 的微批流水要求同时有多个微批在飞，而 MoDM 的档位内批合并已经把批做得较满，再切微批会破坏 CFG 合并带来的前向次数减半收益。所以 PP 只在单档位跨节点、单卡放不下一整段时才用，且要接受气泡代价。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-33\">三十三 · 通信成为瓶颈的三个判据</h3>\n<p>判断通信是否成为瓶颈，不能只看带宽利用率，要看三个量：集合通信时间占单步时间的比例、通信与计算的 overlap 程度、以及批大小对通信的摊薄效应。第一个判据是单步时间分解。设单步计算时间为 T_comp、通信时间为 T_comm，若 T_comm / (T_comp + T_comm) 超过某个阈值，加并行度就不再提速。对 TP 而言 T_comp 随 TP 度近似线性下降，而 T_comm 随 TP 度对数增长（环形 All-Reduce 的步数是 log 级），所以存在一个最优 TP 度；超过它，总时间反而回升。MoDM 的大档位若盲目开到 TP=8，很可能落在回升区间。</p>\n<div class=\"formula\">$$T_{\\text{step}}(p)=\\frac{T_{\\text{comp}}(1)}{p}+\\alpha\\log_2 p\\cdot T_{\\text{lat}},\\quad \\frac{\\partial T_{\\text{step}}}{\\partial p}=0\\ \\Rightarrow\\ p^\\*=f(\\alpha,T_{\\text{lat}})$$</div>\n<p>第二个判据是 overlap。DiT 的注意力与 MLP 之间有依赖，TP 的 All-Reduce 必须等本层计算完才能发起，天然难以与下一层计算重叠，除非做层间流水。这与 LLM 解码阶段可以把通信藏在下一 token 计算背后不同——扩散的每步是完整前向，层间依赖紧。因此扩散推理的 TP 通信更难被隐藏，阈值应比 LLM 更保守。</p>\n<p>第三个判据是批摊薄。通信量与批大小基本无关（All-Reduce 传的是权重梯度或激活分片，与批内 token 数弱相关），而计算量随批线性增长。所以批越大，通信占比越低。MoDM 档位内的 CFG 合并把等效批翻倍、前向次数减半，这直接改善了通信摊薄比：同样的 TP 度，合并后每步只做一次集合通信而不是两次，通信开销减半。这是一个容易被忽略的联动——CFG 合并不仅是算力优化，也是通信优化。</p>\n<p>具体例子：一个大档位在 TP=4 下每层两次 All-Reduce，30 步、24 层，共 1440 次集合通信；若因 CFG 未合并而前向两次，则翻倍到 2880 次。在 NVL72 内单次 All-Reduce 的延迟量级下，这个差异足以让端到端时延出现可测的抬升。反过来，若该档位单卡放得下，TP=1 时通信次数为零，此时任何 TP 都是净损失。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-34\">三十四 · NIXL 传输：档位间与节点间的数据面</h3>\n<p>MoDM 的多档位结构引入了一类 LLM 服务里不常见的数据移动：请求在档位间迁移时的中间状态传递。难度评估器打分后路由，若评估器与小档位同卡，则只需传分数；但若请求在采样中途因队列重平衡被改路由（论文的路由器按队列长度动态调整权重，理论上支持这种重决策），潜变量与采样器状态就要跨档位搬运。这类搬运走 NIXL 的点对点传输比走集合通信更合适：NIXL 面向的是显存到显存、显存到存储的异步传输，支持 RDMA 与 NVLink 路径，适合小消息、低延迟、非规则拓扑的搬运，而不是规整的 All-Reduce。</p>\n<p>工程上要区分两类流量：档位内的 TP/EP 集合通信是规整的、每步都发生的、可用 NCCL 优化；档位间与预填/解码分离场景的 KV 式缓存搬运是不规整的、事件驱动的、用 NIXL 更灵活。MoDM 的 VAE 解码做共享批合并，意味着多个档位的采样结果要汇聚到解码批里——这是一次跨档位的数据汇聚，若档位分布在不同节点，汇聚就走 NIXL。VAE 解码本身是带宽密集的，把多个请求的潜变量拼批解码能摊薄解码阶段单位请求的显存与带宽占用，但拼批前的汇聚传输是新增开销，需要在批大小与传输延迟之间取平衡。</p>\n<p>代价上，NIXL 传输的显存占用是双份的：源端潜变量在传输完成前不能释放，目的端要预分配接收缓冲。对显存本就紧张的档位池，这意味着迁移窗口内峰值显存抬升。因此迁移应尽量发生在采样早期（潜变量还小）而非末期，或者干脆不做中途迁移、只在请求入口做一次性路由。后者更简单，也更符合论文“接入评估→路由→档位内批调度”的流水线顺序。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-35\">三十五 · 把通信代价写进路由目标</h3>\n<p>前文给出的路由目标只含难度分数、单位算力代价与队列长度，没有显式建模通信。但在多档位、多副本部署下，选中一个档位意味着选中它的并行拓扑与通信代价。一个自然的扩展是把 c_k 拆成计算项与通信项：c_k = c_k^comp + c_k^comm，其中通信项随该档位的 TP/EP 度与当前批大小变化。批大时通信项被摊薄，批小时通信项占比高。路由器若知道各档位当前的批大小与并行度，就能避免把请求塞进一个“批很小但 TP 很大”的档位——那种组合的通信占比最高、单请求时延最差。</p>\n<div class=\"formula\">$$\\hat{k}=\\arg\\min_k\\ \\Big(\\frac{s(x)}{c_k^{\\text{comp}}+c_k^{\\text{comm}}(b_k,p_k)}+\\lambda q_k\\Big)$$</div>\n<p>这个改写不改变路由框架，只是把并行与通信的代价显式化。它的工程价值在于：当负载轻、批小的时候，路由器会倾向选择低并行度的小档位（通信近零），而当负载重、批大的时候才把请求导向高并行度的大档位（通信被摊薄）。这与“简单请求走小模型少步数”的原始意图一致，但多了一层对并行拓扑的感知。</p>\n<p>失败模式在这里也很具体：若路由器不知道档位的并行度，可能把一批小请求打进一个 TP=8 的大档位副本，此时每步的 All-Reduce 延迟无法被小批摊薄，端到端时延反而比走单卡小档位更差。这类误路由与难度评估器误判叠加，会造成“难样本进小模型质量回退”与“易样本进大并行档位时延恶化”两种相反的错配。监控上应分别统计档位命中率与各档位的通信时间占比，把后者作为并行配置是否失配的信号。</p>\n<p>最后落到一个可执行的判断：在 NVL72 内，TP 的瓶颈是同步次数而非带宽，因此 TP 度应取到“单步计算时间仍显著大于集合通信延迟”的最小值；EP 的瓶颈是 All-to-All 次数乘以步数，因此只在批足够大时启用；PP 因扩散步串行而气泡难消，只在跨节点不得已时用；档位间搬运用 NIXL 而非 NCCL，且尽量把迁移压在请求入口而非采样中途。把这四条写进档位的部署描述里，路由器的 c_k 才有真实的通信分量可算。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-36\">三十六 · 路由式服务在并行拓扑上的失效边界</h3>\n<p>MoDM 的档位池天然是数据并行（DP）语义：每个档位独立持有一份权重、独立维护队列与 KV 式中间缓存，档位之间不共享参数，因此 TP/EP/PP 只在档位内部才有意义。真正的约束来自显存：档位数量增加会线性抬升权重常驻成本，单卡容量一旦装不下全部档位，就必须把大档位拆到多卡上，此时档位内出现 TP 或 PP，跨卡通信随之进入采样关键路径。DiT 注意力的 All-Reduce 与 CFG 合并批的规模成正比，档位内批越大、TP 度越高，单步迭代里通信占比越重。判断通信是否成为瓶颈的粗略判据是单步计算时间与通信时间之比：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\frac{F}{P_{\\text{sm}}} + \\frac{2\\,(N-1)}{N}\\cdot\\frac{S}{B_{\\text{nvlink}}},\\qquad \\text{瓶颈条件}:\\ \\frac{S}{B} &gt; \\frac{F}{P_{\\text{sm}}}$$</div>\n<p>其中 F 为该步浮点工作量、S 为单次集合通信搬运的字节数、N 为 TP 度。Blackwell 的 NVLink 5 与 NVSwitch 让 N 较小时 All-Reduce 尚可被计算掩盖，但一旦档位内批被 CFG 合并翻倍、中间潜变量以较高精度驻留，S 随批线性增长，而 F 只随批近似线性增长且被量化压缩后进一步缩小，比值便向通信侧倾斜。工程上的直接后果是：小档位本应承担简单请求的低延迟，却因为 TP 组小而通信固定开销占比高，反而失去时延优势；大档位在高峰时被 lambda 导向，队列堆积使尾延迟恶化，此时增加 TP 度并不能救场，只会把瓶颈从显存搬到链路。</p>\n<table class=\"mini\"><thead><tr><th>切分方式</th><th>适用位置</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>DP（档位间）</td><td>模型池各档位独立部署</td><td>显存线性驻留</td><td>单卡装不下全部档位</td></tr><tr><td>TP（档位内）</td><td>大档位跨卡放置</td><td>每步 All-Reduce</td><td>批大、精度高时通信占比上升</td></tr><tr><td>PP（档位内）</td><td>超大骨干分段</td><td>流水气泡、激活搬运</td><td>步数少、批小时气泡无法摊薄</td></tr><tr><td>EP（若采用）</td><td>稀疏专家骨干</td><td>All-to-All 不均衡</td><td>路由偏斜导致热点卡排队</td></tr></tbody></table>\n<p>传输层的关键判断是：档位间不需要 All-to-All，只需要请求元数据与潜变量的点对点搬运，NIXL 这类传输抽象适合承担评估器、路由器与解码批之间的轻量数据移动；而档位内的 All-Reduce 必须走 NVLink 域，跨节点则会引入 RDMA 与 NCCL 的额外跳数。VAE 解码做共享批合并时，若解码卡与采样卡不在同一 NVLink 域，潜变量回传会成为新的隐性瓶颈，抵消批合并带来的带宽摊薄。因此 MoDM 的并行设计应以“档位内尽量单卡、档位间用 NIXL 松耦合”为首选，只有在单卡容量确实不足时才引入 TP/PP，并把通信判据纳入路由目标——当某档位 TP 组的链路利用率接近饱和时，lambda 应把请求导向低负载档位而非继续堆批。</p>\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-37\">三十七 · 精度塌陷：误路由是静默的，不是崩溃的</h3>\n<p>MoDM 最危险的失败模式不是报错，而是“看起来正常”。难度评估器给出分数 s(x)，路由器按 <span class=\"formula\">$$\\hat{k}=\\arg\\min_{k}\\big(s(x)/c_k+\\lambda q_k\\big)$$</span> 选档；一旦 s(x) 偏低，难样本被送进最小档位，用小模型少步数跑完，流水线不抛异常、不超时、不 OOM，图像照常返回——只是细节、文字、结构一致性悄悄退化。这类退化在服务侧没有任何硬信号，只能靠质量监控捕获。工程上必须把“路由决策”与“输出质量”做成可关联的日志：每条请求记录 s(x)、命中档位 k、实际步数、CFG 缩放、潜变量范数与 VAE 解码耗时，并按档位分桶统计。诊断时看两个量：一是档位间质量指标的分布偏移（同一提示词集合在小档位与大档位上的差异），二是误路由率的代理指标——例如同一提示词在不同档位下输出的感知距离，超过阈值即判定该请求被低估。回滚手段不是改模型，而是抬高路由阈值分界点或对 s(x) 加安全裕量，把边缘样本推向大档位；代价是平均步数上升，吞吐下降，这是精度与算力之间的直接兑换。</p>\n<p>具体机制上，评估器本身是一次额外前向，其输入特征轻量但表达力有限，对长提示词、罕见组合、密集文字类请求的区分度最差。工程判断：对提示词长度超过阈值或含文字渲染意图的请求，直接绕过评估器强制走高档位，用规则兜底替代模型打分，牺牲少量算力换掉一整类静默降级。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-38\">三十八 · OOM：显存驻留是常数项，不是峰值项</h3>\n<p>多档位模型池的显存账要和单模型服务分开算。单模型服务的显存峰值由最大批的激活与 KV 式中间缓存决定；MoDM 的显存是“各档位权重常驻 + 档位内批激活 + 共享 VAE 解码批”三项叠加，档位数量增加会线性抬升驻留成本。这意味着 OOM 往往不发生在最大档位跑大 batch 时，而发生在小档位被高峰流量灌满、批大小被队列阈值顶上去、同时大档位权重仍占着显存的时候。诊断顺序应当是：先看各档位权重驻留是否挤占了激活预算，再看 CFG 合并后等效批大小翻倍带来的激活膨胀，最后看 VAE 解码批是否与采样批并发驻留。CFG 正负分支合并成一次前向把前向次数减半，但等效批大小翻倍，激活显存随之上升，这是容易被忽略的隐性成本。</p>\n<p>回滚与防御手段有三层：其一，给每个档位设硬性批大小上限而非仅靠队列阈值，让 OOM 变成可控的排队而不是崩溃；其二，VAE 解码批与采样批做显存配额隔离，解码阶段不允许采样阶段无限制占用；其三，档位权重按需驻留或分时复用——小档位权重可换出到主机内存，代价是切换时的传输延迟，属于用带宽换容量的典型取舍。监控上应采集每档位的显存水位、批大小分布与被拒绝请求数，把“接近上限”作为扩容或调阈值的触发条件，而不是等 OOM 发生。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-39\">三十九 · 批抖动：队列长度进了目标函数，抖动就会传导</h3>\n<p>路由目标里含 λq_k，队列长度是决策变量，这带来一个结构性风险：档位负载变化会改变路由结果，路由结果又反过来改变队列长度，形成反馈环。高峰时某档位队列变长，λ 把请求推向低负载档位，低负载档位瞬间被灌满、队列变长，又把请求推回去——批大小在档位间来回跳，GPU 利用率出现锯齿，尾延迟被放大。批抖动的诊断信号是：同一档位连续窗口内批大小方差过大、档位命中率在短时间内反复翻转、CFG 合并批的有效利用率下降。工程上要给路由加阻尼：对 q_k 做滑动平均而非瞬时值，给档位切换设最小驻留时间或滞回区间，避免单条请求在相邻档位间震荡。</p>\n<p>另一个抖动源是批合并的超时策略。批大小由队列阈值与超时共同决定，超时太短则批小、单位请求的 VAE 与注意力开销摊不薄；超时太长则尾延迟恶化。诊断要看批大小与端到端时延的联合分布，而不是只看均值。回滚手段是把路由权重 λ 调低、让难度分数主导决策，接受一定的档位不均衡，换取批大小的稳定；这本质上是把负载均衡的收益换成可预测的延迟分布。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-40\">四十 · 尾延迟：均值好看不代表 SLO 达标</h3>\n<p>MoDM 的尾延迟有三个独立来源，必须分开定位。第一是评估器开销：每次请求都多一次前向，它在小 batch 下占比更高，低并发时反而拖慢单请求时延。第二是档位排队：难样本集中到大档位，大档位步数多、单请求驻留久，队列尾部被拉长，λ 只能缓解不能消除。第三是 VAE 解码批的同步等待：共享解码批要等批内最慢的采样完成，一个走大档位多步数的请求会把同批的简单请求一起拖住。诊断方法是按阶段打点：接入评估、路由等待、采样迭代、解码等待，分别统计 P50 与 P99，看尾延迟落在哪一段。若 P99 集中在解码等待，说明批合并策略把长短请求混在一起，应改为按档位或按预估步数分桶解码；若集中在大档位排队，则应提高 λ 或为大档位单独扩容。</p>\n<p>论文未给出大规模并发下的尾延迟数据，这意味着 SLO 承诺不能直接引用吞吐数字。工程判断：上线前必须自建压测，用混合难度负载测出各档位的时延分布，并把路由阈值校准与压测绑定；对尾延迟敏感的客户走独立档位或独立队列，避免与批量吞吐流量共享批。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-41\">四十一 · 静默降级与监控面：把不可见变成可告警</h3>\n<p>静默降级的本质是系统在“合法路径”上给出了低质量结果，因此监控必须覆盖质量维度而不只是可用性维度。可落地的监控面包括：路由命中率按档位分桶（命中率突然偏向小档位即为异常）、评估分数分布漂移（提示词分布变化会让校准失效）、档位间同提示词输出的一致性抽样、CFG 合并批的有效批大小、VAE 解码批的等待时长、各档位显存水位与批大小方差。这些指标要能回连到具体请求，否则定位只能靠猜。诊断流程建议固定为：先看质量指标是否按档位分层退化，再看路由日志确认是否误判，再看队列与批大小确认是否抖动，最后看显存与解码确认是否资源挤压。</p>\n<p>回滚策略要分级而非一刀切。一级回滚是调参：抬高阈值分界点、加大 λ、缩短批超时，分钟级生效，代价是吞吐。二级回滚是路由旁路：关闭评估器、全部请求走固定中档位，回到类单模型服务，牺牲自适应收益换确定性。三级回滚是档位下线：把出问题的大档位从池中摘除，请求被导向相邻档位，质量下限下降但服务不中断。每一级都要有预设的触发指标与责任人，避免在故障现场临时决策。校准本身是部署期参数调优而非训练，因此回滚不需要重训模型，这也是 MoDM 在运维上的实际优势——但前提是阈值、λ、批超时这些参数被当作可版本化、可灰度的配置管理，而不是散落在代码里的常量。</p>\n<p>最后落到一个具体机制上：把评估器的安全裕量做成按提示词类别可配的偏移量，对文字渲染与高细节类请求加正偏移强制升档，对纯色块与简单构图类请求加负偏移允许降档，偏移量随离线质量抽检结果滚动校准。这样静默降级的最大来源被规则化收口，剩余风险集中在偏移量本身的漂移上，而漂移可以用档位间一致性抽样直接观测。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-42\">四十二 · 路由式服务的失效边界与可观测性设计</h3>\n\n<p>MoDM 的收益来自“按难度分配算力”，但同一机制也定义了它的失效面：路由决策是开环的，一旦评估器打分与真实采样难度脱钩，系统会把难样本送进小档位，采样步数少、骨干容量小，输出质量塌陷却不会抛异常——这是典型的静默降级。定位这类故障不能只看端到端时延，必须在请求粒度上记录三元组（s(x)、命中档位 k、实际步数），并按提示词类别分桶统计各档位的重采样率与人工/自动质量评分。工程上可设一个在线探针：对每个档位按固定比例抽样，用小档位结果与大档位结果做感知相似度比对，偏差超阈值即触发路由阈值回滚。代价是探针本身消耗额外采样算力，抽样比例需与节省的步数做权衡，通常只在灰度窗口开启。</p>\n\n<p>第二类失效是显存与批抖动。各档位权重常驻显存，档位数量线性抬升驻留成本；CFG 正负分支合并使等效批大小翻倍，采样中间潜变量与 VAE 解码批同时驻留，峰值显存出现在“采样刚结束、解码批尚未释放”的窗口。若路由器只看队列长度 q_k 而不看档位剩余显存，高峰时会把请求堆到同一档位，触发 OOM 或迫使调度器降批，批大小在相邻批次间反复跳变，形成吞吐抖动。诊断应把每档位的显存水位、批大小序列与队列深度对齐到同一时间轴，抖动表现为批大小方差骤增而队列不降。缓解手段是给路由目标加显存约束项，或对档位设最大在途请求数，超出即溢出到相邻档位。</p>\n\n<div class=\"formula\">$$\\text{尾延迟风险}\\propto \\lambda\\,q_k+\\frac{s(x)}{c_k}\\Big|_{\\text{误判}},\\quad \\text{回滚条件：}\\ \\Delta\\text{Quality}&gt;\\tau_q\\ \\text{或}\\ \\text{OOM}&gt;0$$</div>\n\n<p>第三类是尾延迟与 SLO 承诺。lambda 权重把请求导向低负载档位以避免热点排队，但这本质是用质量换时延：低负载档位往往是小模型，重负载下大量请求被“降档”，尾延迟改善而质量分布左移。因此 SLO 必须写成双约束——时延分位数与质量下限同时约束，不能只引用平均计算量下降。上线策略应是档位映射与 lambda 的灰度回滚：先固定阈值跑基线，再按队列长度小步调 lambda，每次变更保留可回退的配置快照；监控面板至少包含各档位命中率、误路由抽样偏差、批大小方差、单卡显存峰值与解码批等待时长。论文未给出大规模并发下的尾延迟数据，任何容量规划都应把档位切换与批合并的调度开销计入，而不是直接外推平均步数收益。</p>\n\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度塌陷（静默降级）</td><td>小档位重采样率上升、抽样相似度下降</td><td>请求粒度三元组审计 + 分桶质量评分</td><td>收紧路由阈值，难样本强制升档</td></tr><tr><td>OOM / 批抖动</td><td>显存峰值贴近上限、批大小方差骤增</td><td>显存水位与批序列时间轴对齐</td><td>档位在途上限 + 显存约束项</td></tr><tr><td>尾延迟恶化</td><td>P99 抬升而均值平稳、降档比例上升</td><td>lambda 变更前后分位数对比</td><td>回退 lambda 与档位映射快照</td></tr></tbody></table>\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-43\">四十三 · 口径的第一原则：先分清“论文报了什么”与“论文没报什么”</h3>\n<p>读 MoDM 的实验部分，第一件事不是看提升倍数，而是把可引用事实与不可引用事实分开。论文明确给出的只有结构性结论：混合难度负载下，路由到多档位模型池可降低平均采样计算量并维持图像质量；档位过少收益有限、过多则显存与调度开销上升。论文没有给出吞吐提升比例、质量指标数值、硬件配置、并发规模、提示词长度分布、批大小阈值、SLO 指标数值与尾延迟数据。这意味着任何“MoDM 在 B200 上把吞吐提高 N 倍”的表述都不是来自原文，而是二次加工。工程读者在评审内部方案时，应把 MoDM 的结果定位为“方向性证据”：它证明按难度分配算力在服务化形态下可行，但不提供可直接代入容量模型的系数。</p>\n<p>由此产生的口径规则是：凡涉及绝对数值的对比，必须标注“原文未给出”；凡涉及相对趋势的对比，必须限定在论文实际比较的基线内——单一扩散模型固定步数服务，以及固定档位不路由的模型池服务。后者尤其容易被忽略：固定档位模型池已经摊薄了部分开销，MoDM 的增益是相对于“有池但不路由”而非“单模型”，把增益归因于“多模型”本身是错的，真正的增量来自路由决策。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-44\">四十四 · 模型档位与硬件档位：两个维度不能混为一谈</h3>\n<p>MoDM 的“档位”指模型池内不同参数规模的扩散/流匹配骨干，由小到大排列，各档位独立维护权重与 KV 式中间缓存。这与 Blackwell 的硬件档位（B200/B300 单卡、GB200/GB300 NVL72 机架）是两个正交维度。论文未给出硬件配置，因此不能假设档位映射到特定 GPU 型号；工程上更合理的读法是：模型档位是算力分配的粒度，硬件档位是承载这些档位的物理边界。单卡容量约束直接决定能常驻几个档位——档位数量增加会线性抬升显存驻留成本，这是论文明确指出的主要约束。</p>\n<p>把这两个维度混读会导出错误结论。例如“在小卡上部署全部档位”在显存上不可行，而“在大卡上只部署一个档位”则退化为基线。可行的部署形态是档位子集加动态加载，但论文未讨论档位切换的权重换入开销，这一项在工程上必须自行测量：权重换入的带宽代价可能吃掉路由节省的算力。用公式表达驻留约束：</p>\n<div class=\"formula\">$$\\sum_{k\\in S} M_k + M_{\\text{eval}} + B_{\\max}\\cdot M_{\\text{act}} \\le M_{\\text{GPU}}$$</div>\n<p>其中 $S$ 为常驻档位集合，$M_k$ 为档位 $k$ 的权重显存，$M_{\\text{eval}}$ 为难度评估器占用，$B_{\\max}\\cdot M_{\\text{act}}$ 为最大批的激活与中间缓存。这个不等式是读 MoDM 显存口径的锚点：论文说“多档位显著增加显存驻留”，落到工程上就是 $|S|$ 受上式约束，档位数量消融的收益曲线在 $S$ 触顶时必然走平。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-45\">四十五 · batch、CFG 合并与并发：等效批大小的口径陷阱</h3>\n<p>MoDM 在档位内做批合并，并把 CFG 正负分支拼成一个批一次前向。这带来一个极易误读的口径问题：等效批大小翻倍而前向次数减半。报告 batch 时若不区分“请求数”与“前向批大小”，吞吐数字会凭空放大。设档位内合并了 $n$ 个请求，CFG 合并后单次前向的批为 $2n$；若按请求数报 batch=8，实际前向批是 16，注意力与 DiT 算力开销按 16 计。正确口径应同时给出请求批 $n$、前向批 $2n$ 与每请求前向次数，三者缺一不可。</p>\n<p>并发维度同样需要拆开。论文未给出并发规模，因此“高并发下路由仍有效”属于未验证断言。可推演的机制是：路由器用 $\\lambda q_k$ 项把请求导向低负载档位，队列越长惩罚越大，这在中等并发下能抑制热点档位排队；但并发升高后，各档位队列同时变长，$\\lambda q_k$ 项趋于均匀，路由退化为按难度分数分配，负载均衡能力下降。尾延迟恰在此处恶化——论文明确缺少大规模并发下的尾延迟数据，所以任何 SLO 承诺都不能建立在 MoDM 的路由均衡上，必须自行压测。</p>\n<table class=\"mini\"><thead><tr><th>报告项</th><th>易错口径</th><th>正确口径</th></tr></thead><tbody><tr><td>batch</td><td>只报请求数</td><td>请求批 $n$ + 前向批 $2n$</td></tr><tr><td>吞吐</td><td>图像/秒不标档位分布</td><td>按档位命中率加权，标注负载难度分布</td></tr><tr><td>显存</td><td>只报单档位权重</td><td>常驻档位总和 + 评估器 + 最大批激活</td></tr><tr><td>时延</td><td>只报均值</td><td>分档位报 TTFT/TPOT，另报尾部分位</td></tr></tbody></table>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-46\">四十六 · 指标口径：TTFT/TPOT 在扩散服务里要重新定义</h3>\n<p>把 LLM 的 TTFT/TPOT 直接套到图像生成上会失真。扩散采样是固定步数的迭代，没有自回归的逐 token 解码，因此“首 token 时间”应映射为“首步潜变量产出时间”或“首个可感知中间结果时间”，“每 token 时间”应映射为“每步去噪时间”。MoDM 的档位配置改变步数，使这两个指标随路由结果变化：小档位步数少，单请求端到端时延低；大档位步数多，单请求时延高但质量达标。服务级指标因此不能只看单请求时延，而要看按档位命中率加权的端到端时延分布。</p>\n<p>设档位 $k$ 的命中率为 $h_k$，步数为 $T_k$，单步时间为 $\\tau_k$，则平均端到端时延的粗估为：</p>\n<div class=\"formula\">$$\\bar{L} = \\sum_{k} h_k \\big( T_k \\tau_k + L_{\\text{eval}} + L_{\\text{VAE},k} \\big)$$</div>\n<p>这个式子暴露两个口径问题。其一，$L_{\\text{eval}}$ 是每请求固定成本，论文承认评估器引入额外前向，它不随档位缩小而消失，简单请求走小模型时评估开销占比反而上升，这是“平均计算量下降”与“平均时延下降”不一定同向的原因。其二，$L_{\\text{VAE},k}$ 因共享批合并而与批大小相关，批越大单位请求解码开销越低，但批等待本身增加时延，二者需在容量规划里联合调。吞吐口径同理：图像/秒必须标注档位命中率与批等待策略，否则不同负载分布下的数字不可比。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-47\">四十七 · 功耗与带宽：论文未报，但必须纳入口径</h3>\n<p>论文未给出功耗数据，这在 Blackwell 档位上是一个显著缺口。多档位常驻意味着更多权重驻留显存，静态功耗与显存带宽占用随档位数量上升；而路由带来的算力节省主要发生在动态计算侧。二者相抵后净功耗是否下降，论文无法回答。工程读法是：把 MoDM 的收益定位在“动态算力与显存带宽的按需分配”，而非“整机功耗下降”。在 NVL72 这类机架形态下，档位间独立部署、档位内批并行，跨档位的负载不均会造成机架级功耗分布倾斜，这一点在容量规划时必须用实测补齐。</p>\n<p>带宽口径还有一个易被忽略的细节：CFG 合并把正负分支拼批，前向次数减半直接摊薄了 DiT 注意力的算力与权重读取带宽；但等效批翻倍也抬高了单次前向的激活带宽。净效应取决于该档位的算术强度——小档位权重小、算术强度低，更偏带宽受限，合并收益更明显；大档位算力受限，合并主要省的是前向启动与调度开销。因此“CFG 合并提升吞吐”不能跨档位统一引用，必须分档位报。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-48\">四十八 · 哪些提升不可比：四条硬边界</h3>\n<p>综合上述，MoDM 的结果在四类对比中不可直接比较。第一，跨硬件不可比：论文未给硬件配置，任何把结果搬到 B200/B300/GB200 的换算都缺少锚点，尤其 tcgen05、TMEM 与 2-SM MMA 的利用程度会显著改变单步时间。第二，跨负载分布不可比：路由收益随难度分布变化，简单请求占比高的负载收益大，全难样本负载下路由退化为全走大档位，收益趋零；报告吞吐必须附负载难度分布。第三，跨基线不可比：相对单模型固定步数与相对固定档位模型池是两个不同基线，前者包含“多档位”与“路由”两项增益，后者只含路由增益，混用会高估路由价值。第四，跨质量约束不可比：论文只定性说“维持图像质量”，未给质量指标数值与质量下限定义；在更严质量下限下，路由阈值需上移，更多请求被推到大档位，算力节省收窄。质量约束的口径必须与阈值校准一起报，否则“质量维持”无法复核。</p>\n<p>落到工程判断上：MoDM 的可复用结论是路由目标函数 $\\hat{k}=\\arg\\min_k (s(x)/c_k+\\lambda q_k)$ 这一联合决策形式，以及档位内 CFG 合并与共享 VAE 解码批这两项摊薄机制；不可复用结论是任何具体倍数。部署时先用离线难度分布与各档位质量—步数曲线校准阈值，再以实测的评估器开销、档位驻留显存与尾延迟反推 $\\lambda$ 与档位子集 $S$，把论文的方向性证据转成自己的容量参数——这一步没有捷径，论文未给出的数字只能由本地压测补齐。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-49\">四十九 · 口径边界：哪些提升能横向比较，哪些不能</h3>\n<p>读 MoDM 的数字，第一步是确认比较对象是否同一口径。论文基线有两类：单一扩散模型固定步数服务，以及固定档位不路由的模型池服务。前者改变的是“算力分配策略”，后者改变的是“是否路由”。只有与固定档位模型池对比，才能把收益归因于难度评估与路由；与单一模型对比时，收益里混入了模型池本身带来的容量与调度开销。更关键的是，MoDM 的收益依赖负载难度分布：路由目标 <span class=\"formula\">$$\\hat{k}=\\arg\\min_{k}\\big(s(x)/c_k+\\lambda q_k\\big)$$</span> 中 s(x) 的分布决定了多少请求落到小档位。混合难度负载下平均步数下降，在难度集中的负载上收益会收窄甚至反转——全部请求都难时，小档位几乎不被命中，模型池退化为大模型加评估器开销。</p>\n<p>指标必须分档读。端到端时延由评估器前向、路由决策、档位内批等待、采样迭代与共享 VAE 解码批五段构成，TTFT 与 TPOT 在扩散服务里对应的是首帧潜变量产出与每步迭代节奏，而非自回归的 token 节奏；把 LLM 服务的 TTFT/TPOT 口径直接套到图像请求上会误读。吞吐要区分“请求/秒”与“像素或图/秒”，后者受分辨率与批合并效率影响。显存侧，多档位权重常驻使驻留成本随档位数近似线性抬升，这是单卡容量下的硬约束，不能与单模型服务的显存数字直接并列。功耗与带宽则被 CFG 合并改变：正负分支拼成一个批一次前向，等效批大小翻倍而前向次数减半，注意力与 DiT 的算力与带宽占用被摊薄，但单次前向的激活峰值上升，显存瞬时占用并非同比例下降。</p>\n<p>不可比的提升主要有三类。其一，未给出硬件档位与并发规模的吞吐比例，无法跨平台换算；Blackwell 上的 NVFP4/FP8 量化若只作用于部分档位，档位间精度不一致会污染质量对比。其二，质量指标口径不明时，“维持质量”不能与基线质量数值并列，误路由导致的质量回退是分布尾部的偶发事件，均值指标会掩盖它。其三，缺少大规模并发下的尾延迟数据，P99 不能由均值外推；队列权重 λ 在高峰把请求导向低负载档位，短期看是负载均衡，长期看是把难请求推给非最优档位，尾延迟与质量同时承压。工程判断应落在：把评估器开销与误路由率作为固定成本计入容量规划，按档位分别压测而非合并报告，并在上线后监控路由命中率与各档位队列长度，用离线质量—步数曲线校准阈值，而不是引用未给出的吞吐数字做 SLO 承诺。</p>\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-50\">五十 · 迁移的第一道闸：难度信号从哪来</h3>\n<p>MoDM 的可迁移性不取决于模型池本身，而取决于难度评估器能否在目标领域里给出与质量强相关的标量分数 s(x)。图像生成里 s(x) 可以来自提示词长度、词表稀有度、文本编码器隐状态的范数或一个轻量分类头；换到视频生成，请求难度还叠加了时长、帧率与运动幅度，单一标量不足以覆盖时间维度的计算量差异，需要把 s(x) 拆成空间分辨率项与时间长度项分别进入路由目标。换到 3D 生成或分子构象采样，难度更多体现在采样步数收敛性而非提示词语义，评估器必须改为对中间潜变量的方差或能量做在线估计，这意味着评估开销从“一次轻量前向”变成“若干步采样的副产物”，路由决策被迫后移到采样开始之后，档位切换窗口收窄。</p>\n<p>工程判断是：评估器与目标领域的难度来源必须同构。若目标领域的难度主要由输出维度（分辨率、帧数、token 数）决定，评估器可以退化为解析式规则，几乎零成本；若难度主要由内容语义决定，则必须保留学习式评估器，并接受其固定开销。后者在 Blackwell 上的代价是每个请求多一次小模型前向，摊到单卡上表现为固定延迟项，当档位间算力差小于该固定项时，路由净收益为负——这是迁移时必须先测的盈亏平衡点，而不是先搬代码。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-51\">五十一 · 路由目标函数要重写代价项</h3>\n<p>原目标 <span class=\"formula\">$$\\hat{k}=\\arg\\min_{k}\\ \\Big(\\frac{s(x)}{c_k}+\\lambda\\,q_k\\Big)$$</span> 中 c_k 是档位单位算力代价，在图像 DiT 上近似正比于参数量与步数乘积。迁到自回归式或混合架构（如带扩散头的 VLM）时，c_k 不再是常数，而是随序列长度变化的函数：预填阶段代价正比于输入 token 数的平方项，解码阶段正比于 KV cache 长度。此时把 c_k 写成标量会系统性高估小档位在长输入上的优势，导致长提示词被误路由到小模型。正确做法是把 c_k 展开为 <span class=\"formula\">$$c_k(n)=a_k n^2 + b_k n + d_k$$</span> 形式的分段代价模型，其中 n 为有效序列长度，系数由离线 profiling 拟合，路由时按请求实际长度取值。</p>\n<p>队列项 λ q_k 的迁移更微妙。图像服务里档位队列长度是纯等待时间代理；在分离式预填/解码架构下，q_k 必须拆成预填队列与解码队列两个分量，因为预填受算力约束、解码受显存带宽约束，二者过载时对尾延迟的贡献不同。把单一 q_k 迁过去会让路由器把请求导向“预填空闲但解码拥塞”的档位，尾延迟反而恶化。代价体现在调度器需要维护二维队列状态并做加权，状态更新频率上升，路由决策本身从 O(K) 变成 O(K) 带两次查表，在高峰并发下这部分 CPU 开销不可忽略。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-52\">五十二 · 模型池的显存驻留是硬上限</h3>\n<p>档位数量 K 线性抬升常驻显存，这是 MoDM 迁移时最先撞到的墙。以 Blackwell 单卡容量为约束，若每个档位权重占 W_k，中间缓存与 VAE 解码批占 R，则可行条件为 <span class=\"formula\">$$\\sum_{k=1}^{K} W_k + R \\le B_{\\max}$$</span> 在 B200 级显存下，K=3 到 4 个不同规模骨干已接近上限，再增加档位就必须引入权重换入换出或档位间共享部分层。迁到视频或多模态模型时单档位权重更大，K 往往被迫降到 2，此时路由收益主要来自步数差异而非模型规模差异，MoDM 的核心假设（规模跨度带来质量跨度）被削弱。</p>\n<p>可行的迁移路径是档位间参数共享：小档位作为大档位的子网络，只常驻一份主干加多组轻量适配头，显存从 ΣW_k 降为 W_max 加少量增量。代价是档位间质量差异变小、路由区分度下降，且子网络结构要求目标模型本身支持弹性宽度，并非所有预训练扩散骨干都满足。另一个方向是把大档位放到独立卡上做分离式部署，路由变成跨卡调度，此时瓶颈从显存转为 NVLink 带宽与跨卡队列同步，NIXL 式的传输层成为必需组件，迁移工作量从改路由代码升级为改部署拓扑。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-53\">五十三 · 批合并与 CFG 合并的适用边界</h3>\n<p>档位内 CFG 正负分支合并为一个批、一次前向，等效批大小翻倍而前向次数减半，这是 MoDM 最直接可迁移的机制，因为它不依赖模型结构，只依赖采样器是否使用 CFG。迁到不使用 CFG 的流匹配蒸馏模型或一致性类采样器时，该机制直接失效，档位内批大小减半，注意力算力摊薄效果消失，路由收益需要重新核算。迁到带引导区间的采样器（guidance schedule 随步数变化）时，正负分支不能简单拼批，因为不同步的引导强度不同，拼批会引入数值不一致。</p>\n<p>共享 VAE 解码批的迁移边界在于解码器是否可批处理且显存可控。图像 VAE 解码单请求显存占用小，拼批摊薄带宽收益明显；视频 VAE 解码的中间激活随帧数线性增长，拼批会迅速吃满显存，实际可拼批大小受最长的那个请求支配，短请求被长请求拖累，形成批内尾延迟。工程上需要按输出维度分桶再拼批，桶边界由显存预算反推，这等于在 MoDM 的档位维度之外再加一个维度，调度复杂度上升一个量级。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-54\">五十四 · 规模上限与不适用场景</h3>\n<p>MoDM 的收益随负载难度分布的方差增大而增大。若请求难度集中（全部简单或全部困难），路由退化为固定档位，额外付出评估器开销与多档位显存却拿不到平均算力下降，此时单模型固定步数是更优解。同理，在低并发场景下队列长度 q_k 恒为零，λ 项失效，路由只剩难度匹配，而低并发本身意味着批合并收益微弱，CFG 合并的算力摊薄也无从体现，整套方案的固定成本无法被摊薄。规模上限因此不在单卡算力，而在“并发足够高、难度分布足够散”这两个前提是否成立。</p>\n<p>不适用场景还包括质量下限极严的请求：误路由到小模型造成的质量回退在离线指标上可能被平均值掩盖，但在线难以发现，因为服务侧只看到输出图像而无参考真值。迁移到医疗影像、工业检测等对单样本质量零容忍的领域时，路由必须加保守偏置，把 s(x) 的分界点整体向大档位偏移，代价是平均算力下降幅度收窄，MoDM 的经济性主张被削弱。可行的折中是双阈值滞回：分数高于上界强制大档位，低于下界走小档位，中间灰区按队列状态决定，用滞回带换取误路由率的可控上界。</p>\n<p>最后落在工程判断上：把 MoDM 迁到新领域，先测三件事——评估器开销占端到端延迟的比例、档位间质量差是否大于误路由带来的回退、显存在目标卡上能否容纳至少两个有实质规模差的档位。三者任一不成立，就应退回到单模型加步数自适应或量化压缩的路线，而不是硬搬模型池。路由式服务的本质是把算力按难度分配，这个思想可迁移；但具体的 K、c_k 形式、q_k 维度与批合并策略，必须按目标领域的代价结构重写，照抄目标函数只会把误路由藏进平均值里。</p>\n\n<h3 id=\"paper-modm-efficient-serving-for-image-gen-2025-sec-55\">五十五 · 迁移边界：哪些模型能进池，哪些负载不该路由</h3>\n<p>这套方案的可迁移性首先取决于模型池的“档位可替换性”。MoDM 的收益来自同一采样语义下不同参数规模骨干的算力差，因此迁到新模型族时，必须保证各档位共享同一潜空间维度、同一噪声调度与同一 VAE 解码接口，否则档位间无法共用解码批，CFG 合并也失去意义。以 DiT 类骨干为例，若小档位与大档位的 patch size 或通道宽度不同，潜变量形状不一致，跨档位批合并直接失效，只能退化为档位内批合并，VAE 摊薄收益随之消失。迁到流匹配采样器时，档位配置的不只是步数，还有 solver 阶数与时间步网格，路由表必须从“分数→档位”扩展为“分数→档位×步数×solver”，校准维度从一维变成三维，离线校准成本显著上升。反过来，若目标领域是视频生成或 3D 生成，单请求的潜变量序列长度远高于图像，档位内批大小被显存压到很小，CFG 合并带来的等效批翻倍会直接撞上单卡容量上限，此时路由的吞吐收益被显存约束吃掉，方案不再划算。</p>\n<p>失效条件集中在评估器与路由目标的耦合处。路由目标 <span class=\"formula\">$$\\hat{k}=\\arg\\min_{k}\\ \\Big(\\frac{s(x)}{c_k}+\\lambda\\,q_k\\Big)$$</span> 中，s(x) 是评估器给出的标量分数，一旦评估器对某类提示词系统性低估难度，这类请求会被稳定压到小档位，形成“质量回退但不报错”的静默失败——服务侧只能靠离线抽检或质量监控发现，在线延迟指标完全正常。迁到新领域时，评估器的轻量特征（提示词长度、token 分布等）与图像难度的相关性需要重新验证，不能直接沿用图像域的阈值。另一个失效条件是档位数量与显存驻留的线性关系：K 个档位意味着 K 份权重常驻，单卡容量固定时，K 增大挤压的是批大小与中间缓存，而批大小下降又削弱 CFG 合并与 VAE 共享批的摊薄效果，形成负反馈。消融中“档位过少收益有限、过多则显存与调度开销上升”正是这条曲线的两端，迁移时应把 K 当作受显存预算约束的部署参数而非自由超参。</p>\n<p>规模上限由三笔固定成本决定，迁到任何领域都要重新核算。第一笔是评估器前向：每请求一次额外前向，其开销与省下的采样步数之比决定了路由的净收益门槛，当目标模型的单步成本很低（小分辨率、少步数采样器）时，评估器开销可能吃掉全部节省。第二笔是档位驻留显存，K 份权重加各自独立的 KV 式中间缓存，在 B200 这类单卡上直接压缩可并发请求数。第三笔是调度复杂度：档位切换与批合并引入队列管理开销，高峰时热点档位堆积会放大尾延迟，而论文未给出大规模并发下的尾延迟数据，SLO 承诺不能引用未给出的吞吐数字。工程判断是：这套路由适合“请求难度分布宽、单请求算力可观、显存预算足以容纳 2–3 个档位”的图像生成服务；若负载难度分布窄（几乎全难或全易），路由退化为固定档位，收益归零；若单卡显存紧张到只能驻留一个档位，方案不适用，应回到单模型固定步数加量化的路线。</p>\n<table class=\"mini\"><thead><tr><th>迁移场景</th><th>需改动</th><th>主要代价</th></tr></thead><tbody><tr><td>同族不同规模 DiT</td><td>仅校准阈值与档位映射</td><td>档位驻留显存线性上升</td></tr><tr><td>流匹配采样器</td><td>路由表扩展步数与 solver</td><td>离线校准维度增加</td></tr><tr><td>视频/3D 生成</td><td>批大小与 CFG 合并策略重设</td><td>显存挤压，摊薄收益消失</td></tr><tr><td>难度分布窄的负载</td><td>无需路由</td><td>评估器开销纯属浪费</td></tr></tbody></table>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">MoDM: Efficient Serving </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">for Image Gener…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · MoDM: Efficient Serving… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>图像生成提示词负载（数据集名称未给出）</td></tr><tr><td>基线</td><td>单一扩散模型固定步数服务、固定档位不路由的模型池服务</td></tr><tr><td>主要结果</td><td>论文报告在混合难度负载下，路由到多档位模型池可降低平均采样计算量并维持图像…</td></tr><tr><td>消融</td><td>论文对路由阈值、档位数量与队列权重 lambda 做了消融，说明档位过少收…</td></tr><tr><td>局限</td><td>难度评估器本身引入额外前向开销，评估误差会导致难样本被误路由到小模型而质量…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-modm-efficient-serving-for-image-gen-2025 · 共 9 个片段</p>\n";break;}}})();
